    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 返回以node为根的子树高度；如果已经不平衡，返回-1作为标记
    // 方法：getHeight；按题目要求处理输入并返回结果，核心算法见方法体。
    int getHeight(TreeNode* node) {
        if (node == nullptr) return 0;               // 终止条件：空树高度为0
        int leftHeight = getHeight(node->left);      // 递归求左子树高度
        if (leftHeight == -1) return -1;             // 左子树已不平衡，直接剪枝返回
        int rightHeight = getHeight(node->right);    // 递归求右子树高度
        if (rightHeight == -1) return -1;             // 右子树已不平衡，直接剪枝返回
        if (abs(leftHeight - rightHeight) > 1) return -1; // 当前节点左右高度差超过1，标记不平衡
        return max(leftHeight, rightHeight) + 1;      // 正常返回当前子树高度
    }

    // 方法：isBalanced；按题目要求处理输入并返回结果，核心算法见方法体。
    bool isBalanced(TreeNode* root) {
        return getHeight(root) != -1;  // 只要最终返回值不是-1，说明整棵树平衡
    }
};
```


### Go

```go
// 方法：isBalanced；按题目要求处理输入并返回结果，核心算法见方法体。
func isBalanced(root *TreeNode) bool {
    return getHeight(root) != -1 // 只要不是-1，说明整棵树平衡
}

// 返回以node为根的子树高度；不平衡时返回-1
// 方法：getHeight；按题目要求处理输入并返回结果，核心算法见方法体。
func getHeight(node *TreeNode) int {
    if node == nil {
        return 0 // 终止条件
    }
    leftHeight := getHeight(node.Left) // 左子树高度
    if leftHeight == -1 {
        return -1 // 左子树已不平衡，剪枝
    }
    rightHeight := getHeight(node.Right) // 右子树高度
    if rightHeight == -1 {
        return -1 // 右子树已不平衡，剪枝
    }
    diff := leftHeight - rightHeight
    if diff > 1 || diff < -1 {
        return -1 // 高度差超过1，标记不平衡
    }
    if leftHeight > rightHeight {
        return leftHeight + 1 // 正常返回高度
    }
    return rightHeight + 1
}
```

## 总结

- 朴素解法在每个节点都重新算一次子树高度，会造成大量重复计算，时间复杂度会退化到 O(n²)。
- 优化解法把"求高度"和"判断平衡"合并到同一次后序遍历里，用 -1 当作"已发现不平衡"的标记，一旦某个子树标记为不平衡，就立即往上返回，不再继续算下去，实现提前剪枝。
- 优化之后每个节点只访问一次，时间复杂度降到 O(n)，空间复杂度就是递归调用栈的开销 O(h)。
- 这种"用特殊返回值同时携带结果和错误/终止信号"的技巧，在树形递归里是很常见的性能优化手段，值得你在类似题目里举一反三。

07.二叉树/0111.二叉树的最小深度/0111.二叉树的最小深度.md:
# 0111. 二叉树的最小深度

**题目描述**

给定一个二叉树的根节点 `root`，返回其最小深度。最小深度是从根节点到**最近叶子节点**的最短路径上的节点数。

```
示例：
输入: root = [3,9,20,null,null,15,7]
      3
     / \
    9  20
      /  \
     15   7
输出: 2  （根到叶子节点9的路径长度为2）

容易踩坑的示例：
输入: root = [2,null,3,null,4,null,5,null,6]
      2
       \
        3
         \
          4
           \
            5
             \
              6
输出: 5  （因为根节点只有右子树，左子树为空但不是叶子，必须走到最深的6才是叶子节点）
```

## 思路

这题看起来像是"最大深度"的镜像问题，所以很多人会直接照搬最大深度的代码，把 `max` 换成 `min`，结果在某些用例上就翻车了。**问题出在哪呢？

那正确的做法是什么呢？就是在递归里特判一下"当前节点只有一侧子树为空、另一侧不为空"这种情况：这种情况下当前节点不是叶子，不能直接返回较小的那个子树深度（很可能就是0），而必须返回非空那一侧子树的深度加1，因为这条路径必须继续往非空的那一侧走，一直走到真正找到叶子节点为止。

递归这里要分四种情况分别处理：

第一种，左右子树都为空：当前节点自己就是叶子，最小深度是 1。

第二种，左子树为空，右子树不为空：这时候不能走左边，因为无路可走，必须走右边，最小深度就等于右子树最小深度加 1。

第三种，右子树为空，左子树不为空：同理，最小深度等于左子树最小深度加 1。

第四种，左右子树都不为空：这是正常情况，最小深度就是 min(左子树最小深度, 右子树最小深度) 再加 1。

那这里我再跟你说一个更省心的办法——用层序遍历（BFS）来做反而更简单：从根节点开始一层一层往外扩展，**第一次遇到某个节点的左右孩子都为空**的时候（也就是第一次遇到真正的叶子节点），直接返回当前层数就行了，为什么这样可以呢？因为 BFS 保证了先遇到的叶子节点一定是深度最小的那个，根本不需要考虑上面递归里那些特判问题，思路上更干净。

那复杂度怎么样呢？递归法和 BFS 法最坏情况都是 O(n)（树退化成一条链，而且叶子在最底部），但 BFS 在很多情况下可以提前结束，不用把整棵树遍历完；空间复杂度递归是 O(h)，BFS 最坏是 O(n)。

## 代码

### Python

```python
class Solution:
    # 方法：minDepth；按题目要求处理输入并返回结果，核心算法见方法体。
    def minDepth(self, root):
        # 递归法
        if root is None:
            return 0                                # 终止条件
        if root.left is None and root.right is None:
            return 1                                # 叶子节点
        if root.left is None:
            return self.minDepth(root.right) + 1    # 只有右子树，必须走右边
        if root.right is None:
            return self.minDepth(root.left) + 1     # 只有左子树，必须走左边
        return min(self.minDepth(root.left), self.minDepth(root.right)) + 1  # 都存在，取较小值

    # 方法：minDepthBFS；按题目要求处理输入并返回结果，核心算法见方法体。
    def minDepthBFS(self, root):
        # BFS法
        from collections import deque
        if root is None:
            return 0
        queue = deque([root])
        depth = 0
        while queue:
            size = len(queue)
            depth += 1                              # 进入新的一层
            for _ in range(size):
                node = queue.popleft()
                if node.left is None and node.right is None:
                    return depth                    # 第一次遇到叶子节点，直接返回
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
        return depth
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 递归法：注意处理单侧子树为空的特殊情况
    // 方法：minDepth；按题目要求处理输入并返回结果，核心算法见方法体。
    int minDepth(TreeNode* root) {
        if (root == nullptr) return 0;                 // 终止条件：空树深度为0
        if (root->left == nullptr && root->right == nullptr) return 1; // 叶子节点，深度为1
        if (root->left == nullptr) return minDepth(root->right) + 1;   // 只有右子树，必须走右边
        if (root->right == nullptr) return minDepth(root->left) + 1;   // 只有左子树，必须走左边
        return min(minDepth(root->left), minDepth(root->right)) + 1;   // 左右都存在，取较小值
    }

    // BFS法：第一次遇到叶子节点就是最小深度
    // 方法：minDepthBFS；按题目要求处理输入并返回结果，核心算法见方法体。
    int minDepthBFS(TreeNode* root) {
        if (root == nullptr) return 0;
        queue<TreeNode*> que;
        que.push(root);
        int depth = 0;
        while (!que.empty()) {
            int size = que.size();
            depth++;                             // 进入新的一层，深度加一
            for (int i = 0; i < size; i++) {
                TreeNode* node = que.front();
                que.pop();
                if (node->left == nullptr && node->right == nullptr) {
                    return depth;                 // 第一次遇到叶子节点，直接返回
                }
                if (node->left) que.push(node->left);
                if (node->right) que.push(node->right);
            }
        }
        return depth;
    }
};
```


### Go

```go
// 递归法
// 方法：minDepth；按题目要求处理输入并返回结果，核心算法见方法体。
func minDepth(root *TreeNode) int {
    if root == nil {
        return 0 // 终止条件
    }
    if root.Left == nil && root.Right == nil {
        return 1 // 叶子节点
    }
    if root.Left == nil {
        return minDepth(root.Right) + 1 // 只有右子树
    }
    if root.Right == nil {
        return minDepth(root.Left) + 1 // 只有左子树
    }
    leftDepth := minDepth(root.Left)
    rightDepth := minDepth(root.Right)
    if leftDepth < rightDepth {
        return leftDepth + 1 // 都存在，取较小值
    }
    return rightDepth + 1
}

// BFS法
// 方法：minDepthBFS；按题目要求处理输入并返回结果，核心算法见方法体。
func minDepthBFS(root *TreeNode) int {
    if root == nil {
        return 0
    }
    queue := []*TreeNode{root}
    depth := 0
    for len(queue) > 0 {
        size := len(queue)
        depth++ // 进入新的一层
        for i := 0; i < size; i++ {
            node := queue[0]
            queue = queue[1:]
            if node.Left == nil && node.Right == nil {
                return depth // 第一次遇到叶子节点，直接返回
            }
            if node.Left != nil {
                queue = append(queue, node.Left)
            }
            if node.Right != nil {
                queue = append(queue, node.Right)
            }
        }
    }
    return depth
}
```

## 总结

- 最小深度不能简单地把最大深度代码里的 `max` 换成 `min`，因为"叶子节点"要求左右孩子都为空，单侧子树为空的时候不能把那一侧的 0 也拿去比较。
- 递归解法需要对"左空右不空""右空左不空""左右都不空""左右都空"这四种情况分别处理，漏掉中间那两种情况是最容易犯的错误。
- BFS 解法更省心：按层扩展，第一次遇到左右孩子都为空的节点，直接返回当前层数就是答案，完全不需要处理那些特判逻辑。
- 这道题算是理解"叶子节点定义"和"边界条件完整性"的经典题目，提醒你做题的时候一定要把题目定义反复确认清楚，不能想当然地照搬相似题目的模板。

07.二叉树/0112.路径总和/0112.路径总和.md:
# 0112. 路径总和

**题目描述**

给你二叉树的根节点 `root` 和一个表示目标和的整数 `targetSum`，判断该树中是否存在**根节点到叶子节点**的路径，这条路径上所有节点值相加等于 `targetSum`。存在则返回 `true`，否则返回 `false`。

```
示例：
输入: root = [5,4,8,11,null,13,4,7,2,null,null,null,1], targetSum = 22
       5
      / \
     4   8
    /   / \
   11  13  4
  /  \      \
 7    2      1
输出: true
解释: 存在路径 5->4->11->2，和为22
```

## 思路

这道题是"二叉树中递归带着回溯"这个思想的一个直接应用：需要沿着一条从根到叶子的路径把节点值累加起来，等到达叶子节点的时候，判断累加结果是不是等于目标值。

一种直观的写法，跟 0257 题类似，是用一个变量记录"从根到当前节点这条路径上所有值的和"，到达叶子节点时判断这个和是不是等于 `targetSum`。但更简洁的写法是**用减法代替加法**：给递归函数传入一个"剩余目标值"，每往下走一层，就把这个剩余目标值减去当前节点的值，这样递归到叶子节点的时候，只需要判断"剩余目标值有没有恰好减到 0"就行了，不需要额外维护一个"当前路径和"再去跟 `targetSum` 比较，逻辑上更直接一些。

具体怎么做呢？

第一步，递归函数接收当前节点和"剩余需要凑够的目标值" `remain`。

第二步，如果当前节点是空的，直接返回 `false`——空节点不可能构成一条有效路径。

第三步，先用当前节点的值去更新 `remain`，也就是 `remain -= node->val`。

第四步，如果当前节点是叶子节点（左右孩子都是空的），那就判断 `remain` 是不是恰好等于 0，是的话就说明找到了一条满足条件的路径，返回 `true`。

第五步，如果不是叶子节点，就递归地去左子树或者右子树里继续找——只要左子树或者右子树里有一条满足条件的路径就行，所以用逻辑或（`||`/`or`）连接两次递归调用的结果。

这里的"回溯"体现得比 0257 题更隐蔽一些。为什么呢？

时间复杂度是 O(n)，每个节点最多访问一次；空间复杂度是 O(h)，是递归调用栈的开销。

## 代码

### Python

```python
class Solution:
    # 方法：hasPathSum；按题目要求处理输入并返回结果，核心算法见方法体。
    def hasPathSum(self, root, targetSum):
        if root is None:
            return False                 # 空树不存在任何路径
        return self.traverse(root, targetSum)

    # 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
    def traverse(self, node, remain):
        # remain 用值传递（Python整数不可变，天然实现隐式回溯）
        if node is None:
            return False                 # 空节点不构成有效路径
        remain -= node.val               # 抵消剩余目标值
        if node.left is None and node.right is None:
            return remain == 0           # 叶子节点，判断是否恰好凑够
        return self.traverse(node.left, remain) or self.traverse(node.right, remain)  # 任一子树满足即可
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // remain 表示还需要凑够多少值才能达到目标，用值传递天然实现隐式回溯
    // 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
    bool traverse(TreeNode* node, int remain) {
        if (node == nullptr) return false;         // 空节点不构成有效路径
        remain -= node->val;                       // 用当前节点值抵消剩余目标值
        if (node->left == nullptr && node->right == nullptr) {
            // 到达叶子节点，判断是否恰好凑够目标值
            return remain == 0;
        }
        // 只要左子树或右子树中有一条路径满足条件即可
        return traverse(node->left, remain) || traverse(node->right, remain);
    }

    // 方法：hasPathSum；按题目要求处理输入并返回结果，核心算法见方法体。
    bool hasPathSum(TreeNode* root, int targetSum) {
        if (root == nullptr) return false;  // 空树不存在任何路径
        return traverse(root, targetSum);
    }
};
```


### Go

```go
// 方法：hasPathSum；按题目要求处理输入并返回结果，核心算法见方法体。
func hasPathSum(root *TreeNode, targetSum int) bool {
    if root == nil {
        return false // 空树不存在任何路径
    }
    return traverse(root, targetSum)
}

// remain 用值传递（Go中int是值类型），实现隐式回溯
// 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
func traverse(node *TreeNode, remain int) bool {
    if node == nil {
        return false // 空节点不构成有效路径
    }
    remain -= node.Val // 抵消剩余目标值
    if node.Left == nil && node.Right == nil {
        return remain == 0 // 叶子节点，判断是否恰好凑够
    }
    // 任一子树满足即可
    return traverse(node.Left, remain) || traverse(node.Right, remain)
}
```

## 总结

- 用"剩余目标值不断减去当前节点值，到叶子节点判断是不是恰好为0"这种写法，比维护"当前路径和再跟目标比较"更简洁，这两种逻辑是等价的。
- `remain` 这个参数以值传递的方式在递归中往下传，天然就实现了回溯，不需要手动去撤销状态，这是"隐式回溯"在实际题目里的一个具体应用，正好呼应了本系列里专门讲回溯思想的那篇方法论文档。
- 判断是不是存在满足条件的路径，只需要左子树或者右子树里**任意一条**满足就行，用逻辑或连接两次递归结果，不需要把两侧都探索完再去决策。
- 这道题跟 0257 题（收集所有路径）的区别在于：0257 要收集所有的路径，这道题只需要判断"是否存在"一条路径就够了，所以不需要显式维护一个路径列表，只需要维护一个数值即可，是同一类问题在不同要求下的简化版本。

07.二叉树/0116.填充每个节点的下一个右侧节点指针/0116.填充每个节点:
# 116. 填充每个节点的下一个右侧节点指针

**题目描述**

给定一棵**完美二叉树**（每一层的节点都被完全填充，且所有叶子节点都在同一层），树的每个节点除了 `left`、`right` 指针外，还多了一个 `next` 指针。请填充每个节点的 `next` 指针，让它指向其同一层的右侧下一个节点。如果找不到下一个右侧节点，则将 `next` 设为 `null`。初始状态下所有 `next` 指针都为 `null`。

```
示例：
输入: root = [1,2,3,4,5,6,7]
输出: [1,#,2,3,#,4,5,6,7,#]
解释: 给定的二叉树是完美二叉树，
      填充后：第 1 层的 1 的 next 指向 null（因为它是本层唯一节点）
      第 2 层：2 -> 3 -> null
      第 3 层：4 -> 5 -> 6 -> 7 -> null
      （# 表示每层的结尾，即该层最后一个节点的 next 是 null）
```

## 思路

这道题我一般会想到两种解法：一种是比较通用、但要多花点空间的层序遍历；另一种呢，是利用"完美二叉树"这个特殊条件，做到 O(1) 额外空间。我先说说思路，再讲讲为什么最终选了第二种。

**思路一：BFS 层序遍历（通用解法，先说一下）**

最直观的想法就是一层一层处理：用一个队列做标准的层序遍历，每次把一整层的节点都取出来，按从左到右的顺序，依次把前一个节点的 `next` 指向后一个节点，最后一个节点的 `next` 保持 `null` 就行。这个方法的好处是不依赖"完美二叉树"这个特殊条件，随便什么二叉树，只要每层节点顺序明确，都能用。但问题是，队列本身要占 O(n) 的额外空间去存每一层的节点，这就是它的代价。

**思路二：利用已经连好的 next 指针去连下一层（O(1) 额外空间，这道题我用的是这个）**

题目特意限定了是"完美二叉树"，这一点很关键，正是因为有这个条件，才能把队列省掉。你想啊，完美二叉树能保证什么？它保证只要一个节点有孩子，那左右孩子一定是成对出现的，不会出现只有一侧孩子的情况，而且同一层的节点数量都是固定的。

那核心思路是什么呢？说白了就是**利用上一层已经连好的 next 链条，去推出下一层怎么连**。你可以这么想：假设当前这一层（第 k 层）所有节点的 `next` 指针已经全部连好了，形成了一条从左到右的链。那现在要连第 k+1 层，可以这样一步步来：

1. 从第 k 层最左边的节点开始，把它当作"当前层遍历指针"，叫它 `cur`。
2. 对 `cur` 指向的每个节点来说，它左孩子的 `next` 应该指向它自己的右孩子——为什么呢？

那这个方法为什么是对的呢？关键在于它靠的是一个归纳的性质：**只要上一层的 next 链条连好了，就一定能推出下一层的链条怎么连**。根节点自己就是第一层，它天然只有自己一个节点，next 本来就是 null，不需要额外处理，正好可以当作归纳的起点。

再说说边界条件：如果某一层起点节点的 `left` 是空的，那就说明已经到叶子层了（完美二叉树能保证同一层的节点要么都有孩子、要么都没有），这时候就该停止遍历了。另外第 3 步里判断 `cur.next` 是否存在也是必须的，如果 `cur` 已经是本层最后一个节点了，那就不用再做跨节点的连接了。

复杂度这块，两种方法的时间复杂度都是 O(n)，因为每个节点都只会被访问常数次。空间复杂度上就不一样了：BFS 那种方法需要 O(n)（最坏情况下某一层能有 n/2 个节点堆在队列里，量级上还是 O(n)）；而利用已有 next 指针这种做法，只用了几个指针变量，完全不需要队列也不需要递归栈，才是真正意义上的 O(1) 额外空间——当然这里说的不算输入树本身占的空间。

## 代码

### Python

标准库没有针对这种"树内指针原地连接"问题的一行解法，本题只写手写实现：

```python
class Node:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None, next=None):
        self.val = val
        self.left = left
        self.right = right
        self.next = next


class Solution:
    # 方法：connect；按题目要求处理输入并返回结果，核心算法见方法体。
    def connect(self, root: 'Node') -> 'Node':
        if root is None:
            return root

        level_start = root  # 当前层的最左节点，作为每层的起点
        while level_start.left is not None:  # 只要还有下一层（有左孩子）就继续
            cur = level_start  # cur 沿当前层的 next 链条向右移动
            while cur is not None:
                cur.left.next = cur.right  # 同一父节点下，左孩子 next 指向右孩子
                if cur.next is not None:
                    # 跨父节点连接：cur 的右孩子 next 指向 cur.next 的左孩子
                    cur.right.next = cur.next.left
                cur = cur.next  # 沿当前层链条前进，处理下一个父节点

            level_start = level_start.left  # 下移到下一层的最左节点

        return root
```

面试考察点：能不能想清楚"用上一层已经建好的 next 链条去推出下一层"这个归纳思路，尤其是"跨父节点连接"（也就是 `cur.right.next = cur.next.left`）这一步，这是这道题能从 O(n) 空间优化到 O(1) 空间的关键难点所在。

以下四种语言均采用**思路二（O(1) 空间，利用已连接的 next 层间递进）**实现。

### C++

```cpp
class Node {
public:
    int val;
    Node* left;
    Node* right;
    Node* next;

    Node() : val(0), left(nullptr), right(nullptr), next(nullptr) {}
    Node(int _val) : val(_val), left(nullptr), right(nullptr), next(nullptr) {}
};

class Solution {
public:
    Node* connect(Node* root) {
        if (root == nullptr) return root;

        Node* levelStart = root;  // 当前层的最左节点，作为每层的起点
        while (levelStart->left != nullptr) {  // 只要还有下一层（有左孩子）就继续
            Node* cur = levelStart;  // cur 沿当前层的 next 链条向右移动
            while (cur != nullptr) {
                cur->left->next = cur->right;  // 同一父节点下，左孩子的 next 指向右孩子
                if (cur->next != nullptr) {
                    // 跨父节点连接：cur 的右孩子 next 指向 cur.next 的左孩子
                    cur->right->next = cur->next->left;
                }
                cur = cur->next;  // 沿当前层链条前进，处理下一个父节点
            }
            levelStart = levelStart->left;  // 下移到下一层的最左节点
        }
        return root;
    }
};
```


### Go

```go
type Node struct {
    Val   int
    Left  *Node
    Right *Node
    Next  *Node
}

// 方法：connect；按题目要求处理输入并返回结果，核心算法见方法体。
func connect(root *Node) *Node {
    if root == nil {
        return root
    }

    levelStart := root // 当前层的最左节点，作为每层的起点
    for levelStart.Left != nil {  // 只要还有下一层就继续
        cur := levelStart // cur 沿当前层的 next 链条向右移动
        for cur != nil {
            cur.Left.Next = cur.Right // 同一父节点下，左孩子 next 指向右孩子
            if cur.Next != nil {
                // 跨父节点连接
                cur.Right.Next = cur.Next.Left
            }
            cur = cur.Next // 沿当前层链条前进
        }
        levelStart = levelStart.Left // 下移到下一层最左节点
    }
    return root
}
```

## 总结

- BFS 层序遍历是比较通用的解法，思路简单，但代价是要用 O(n) 的队列空间；而利用已经连好的 next 链条逐层往下推的方法呢，能做到 O(1) 额外空间，不过它的代价是只能用在完美二叉树这种同层节点数量固定、左右孩子必定成对出现的特殊结构上。
- O(1) 解法说白了本质就是一个归纳的过程：上一层的 next 链条连好了，才有条件去连下一层，根节点自己就构成了归纳的起点，因为它就一个节点，next 天然是 null。
- 这里最容易出错的地方就是"跨父节点连接"这一步（也就是 `cur.right.next = cur.next.left`），很多人容易只记得去连同一个父节点下的左右孩子，却忘了不同父节点之间在下一层其实也是相邻的，这一步必须单独处理才行。
- 整个循环可以这么理解：外层循环控制的是"还有没有下一层"（通过 `levelStart.left != nil` 来判断，完美二叉树能保证不会出现只有一侧孩子的怪情况），内层循环控制的是"在当前层内从左往右移动，顺便把下一层连好"。这两层循环分别对应着"层间往下推进"和"层内从左到右遍历"，把这两层循环各自的职责想清楚，是写对这道题代码的关键。

07.二叉树/0129.求根到叶子节点数字之和/0129.求根到叶子节点数字之和:
# 129. 求根到叶子节点数字之和

**题目描述**

给定一棵二叉树，树中每个节点都存放一个 0-9 的数字，每一条从根节点到叶子节点的路径都代表一个数字。求所有从根到叶子路径代表的数字之和。

```
示例：
输入: root = [1,2,3]
输出: 25
解释: 从根到叶子节点路径 1->2 代表数字 12，路径 1->3 代表数字 13，12 + 13 = 25
```

```
示例：
输入: root = [4,9,0,5,1]
输出: 1026
解释: 从根到叶子节点路径 4->9->5 代表数字 495
      从根到叶子节点路径 4->9->1 代表数字 491
      从根到叶子节点路径 4->0 代表数字 40
      495 + 491 + 40 = 1026
```

## 思路

这道题说白了就是一次带状态的 DFS，这个状态是什么呢？就是"从根节点一路走到当前节点，已经拼出来的数字"。

那关键的地方在哪呢？就是这个状态要怎么往下传。你想啊，数字的十进制表示其实有个很自然的规律：每往下走一层，就相当于把手上已有的数字整体乘以 10，再加上新节点的值。比如从根节点开始数字是 1，走到值为 2 的子节点，新数字就变成了 `1 * 10 + 2 = 12`；再往下走到值为 5 的子节点，就是 `12 * 10 + 5 = 125`。这个递推关系其实天然就适合用 DFS 的参数往下传，根本不需要额外拼字符串或者用数组记路径。

具体怎么做呢？我设计一个递归函数 `dfs(node, curNum)`，这里的 `curNum` 表示从根节点走到 `node` 的父节点为止，已经拼出来的数字。进到 `node` 之后，先算一下 `curNum = curNum * 10 + node.val`，这样就得到了"包含当前节点"的数字。

- 那如果 `node` 是叶子节点呢（也就是左右孩子都是空的），说明这条路径已经走到底了，直接把这个 `curNum` 加进全局答案里，或者当作返回值往上返回就行。
- 如果不是叶子节点呢，那就把当前算出来的 `curNum` 分别传给左子树和右子树，让它们继续往下递归——为什么要分别传呢？因为二叉树里每一条从根到叶子的路径都是相互独立的，一个节点很可能同时是好几条路径的公共前缀。

边界条件这里要注意两点：第一，空节点直接返回 0，不参与计算（题目已经保证根节点非空，所以空子节点这种情况只在递归内部处理就行）；第二，"叶子节点"的判定一定要左右孩子都为空才算，不能只看某一侧是不是空的，不然会把只有单侧子树的节点错误地当成叶子，提前把路径截断了。

那这里可能有人会问，为什么不用回溯呢，比如先把路径记下来再统一算数字？其实道理很简单：乘 10 加当前值这种"边走边算"的方式，已经把整条路径的信息压缩成了一个数字状态，根本不需要保留整条路径的数组，代码写起来更简洁，而且返回的时候也不需要做撤销操作——这里跟那种经典的回溯场景不一样，经典回溯是多个分支共享同一个可变结构（比如一个列表），需要进去 push、出来 pop；而这道题每次递归传的是值的一份拷贝，天然就不会互相污染，所以完全用不上回溯那套撤销逻辑。

复杂度这块，每个节点只会被访问一次，所以时间复杂度是 O(n)，n 就是节点总数。空间复杂度主要来自递归调用栈，最坏情况下（树退化成一条链）是 O(n)，平均情况下（树高度比较平衡）是 O(log n)。

## 代码

### Python

标准库层面没有直接对应"路径数字求和"的一行解法，本题以手写递归为主：

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：sumNumbers；按题目要求处理输入并返回结果，核心算法见方法体。
    def sumNumbers(self, root: TreeNode) -> int:
        # 方法：dfs；按题目要求处理输入并返回结果，核心算法见方法体。
        def dfs(node: TreeNode, cur_num: int) -> int:
            if node is None:
                return 0  # 空节点不产生数字
            cur_num = cur_num * 10 + node.val  # 拼接当前节点值到已有数字末位
            if node.left is None and node.right is None:
                return cur_num  # 叶子节点，数字已完整，直接返回
            # 非叶子节点，分别递归左右子树，两条路径的 cur_num 互不影响
            return dfs(node.left, cur_num) + dfs(node.right, cur_num)

        return dfs(root, 0)
```

面试考察点：面试官这里主要看你能不能想到"数字 = 父数字 * 10 + 当前值"这个递推式，还有能不能正确处理叶子节点的判定和空节点这些边界条件，而不是单纯看你会不会搭个递归框架。

### C++

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    // 方法：sumNumbers；按题目要求处理输入并返回结果，核心算法见方法体。
    int sumNumbers(TreeNode* root) {
        return dfs(root, 0);  // 从根节点开始，初始已组成数字为 0
    }

private:
    // 方法：dfs；按题目要求处理输入并返回结果，核心算法见方法体。
    int dfs(TreeNode* node, int curNum) {
        if (node == nullptr) {
            return 0;  // 空节点不产生数字，直接返回 0
        }
        curNum = curNum * 10 + node->val;  // 把当前节点值拼接到已有数字末位
        if (node->left == nullptr && node->right == nullptr) {
            return curNum;  // 叶子节点，这条路径的数字已经完整，直接返回
        }
        // 非叶子节点，把 curNum 分别传给左右子树继续拼接，两条路径互不影响
        return dfs(node->left, curNum) + dfs(node->right, curNum);
    }
};
```


### Go

```go
