        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 通用解法：O(n) 后序遍历
    // 方法：countNodesGeneral；按题目要求处理输入并返回结果，核心算法见方法体。
    int countNodesGeneral(TreeNode* root) {
        if (root == nullptr) return 0;               // 终止条件
        int leftCount = countNodesGeneral(root->left);   // 左子树节点数
        int rightCount = countNodesGeneral(root->right); // 右子树节点数
        return leftCount + rightCount + 1;            // 加上自己
    }

    // 优化解法：利用完全二叉树性质，O(log n * log n)
    // 方法：countNodes；按题目要求处理输入并返回结果，核心算法见方法体。
    int countNodes(TreeNode* root) {
        if (root == nullptr) return 0;
        TreeNode* left = root->left;
        TreeNode* right = root->right;
        int leftDepth = 0, rightDepth = 0;
        while (left) { leftDepth++; left = left->left; }    // 一直往左走到底，统计深度
        while (right) { rightDepth++; right = right->right; } // 一直往右走到底，统计深度
        if (leftDepth == rightDepth) {
            // 左右深度相等，说明是满二叉树，直接用位运算公式 2^depth - 1
            return (1 << (leftDepth + 1)) - 1;
        }
        // 不是满二叉树，递归左右子树（其中必有一侧下一层判断会命中满二叉树分支）
        return countNodes(root->left) + countNodes(root->right) + 1;
    }
};
```


### Go

```go
// 通用解法：O(n)
// 方法：countNodesGeneral；按题目要求处理输入并返回结果，核心算法见方法体。
func countNodesGeneral(root *TreeNode) int {
    if root == nil {
        return 0
    }
    leftCount := countNodesGeneral(root.Left)
    rightCount := countNodesGeneral(root.Right)
    return leftCount + rightCount + 1
}

// 优化解法：O(log n * log n)
// 方法：countNodes；按题目要求处理输入并返回结果，核心算法见方法体。
func countNodes(root *TreeNode) int {
    if root == nil {
        return 0
    }
    left, right := root.Left, root.Right
    leftDepth, rightDepth := 0, 0
    for left != nil { // 一直往左走到底，统计深度
        leftDepth++
        left = left.Left
    }
    for right != nil { // 一直往右走到底，统计深度
        rightDepth++
        right = right.Right
    }
    if leftDepth == rightDepth {
        return (1 << (leftDepth + 1)) - 1 // 满二叉树，公式计算
    }
    return countNodes(root.Left) + countNodes(root.Right) + 1 // 递归处理不满的一侧
}
```

## 总结

- 通用解法就是用后序遍历，累加左右子树的节点数就行，能适用于任意二叉树，复杂度是 O(n)。
- 优化解法呢，利用的是完全二叉树"最左路径深度等于最右路径深度时，一定是满二叉树"这个性质，把满二叉树那部分直接用公式 `2^depth - 1` 算出来，不用再一个个节点去访问了。
- 优化解法的递归深度是 O(log n)，每一层还需要花 O(log n) 的时间去统计左右深度，所以总的复杂度是 O(log n × log n)，比通用解法快得多。
- 这道题的价值就在于，它展示了"通用算法 + 特殊结构性质 = 更优解法"这样一种思路，算是数据结构性质应用类题目里比较有代表性的一道。

07.二叉树/0226.翻转二叉树/0226.翻转二叉树.md:
# 0226. 翻转二叉树

**题目描述**

给你一棵二叉树的根节点 `root`，翻转这棵二叉树，并返回其根节点（即每个节点的左右子树互换）。

```
示例：
输入: root = [4,2,7,1,3,6,9]
输出: [4,7,2,9,6,3,1]

     4                4
    / \              / \
   2   7    -->     7   2
  / \  / \          / \ / \
 1  3 6   9        9  6 3  1
```

## 思路

翻转二叉树这个操作说白了本质很简单：**对每一个节点，把它的左右孩子交换一下**。你只要把树里每个节点都做一次这样的交换，整棵树自然就翻转完成了，所以这道题的核心就变成了"怎么去遍历整棵树，并且在遍历的过程中对每个节点做一次交换"。

那这里天然就适合用递归也就是 DFS 来解决：递归函数负责的事情是"翻转以某个节点为根的这棵子树"，单层递归的逻辑就是先交换当前节点的左右孩子，然后再递归去处理交换之后的左子树和右子树——这里递归调用哪个子树先都没关系，因为已经交换过了，两个子树最终都会被处理到。

**这里遍历顺序的选择是个关键点，我来说说三种情况**：

- 前序遍历，也就是先交换根节点，再递归左右子树，这个是可行的，因为交换这个动作只依赖当前节点自身的左右指针，跟子树内部是不是已经翻转完成没关系。
- 后序遍历，先把左右子树各自递归处理完，再交换根节点，这个也是可行的，逻辑就是先把两个子树分别翻转好，再把它们换个位置挂到根节点上。

除了递归，其实也可以用迭代法来写，也就是前序遍历的迭代写法，用栈或者队列都行，只要保证是"每访问到一个节点就交换它的左右孩子"这个原则，遍历顺序其实不影响正确性，唯独中序遍历不行。

时间复杂度是 O(n)，因为每个节点都会被访问一次，并且执行一次常数时间的交换；空间复杂度是 O(h)，也就是递归调用栈的深度，等于树的高度。

## 代码

### Python

```python
class Solution:
    # 方法：invertTree；按题目要求处理输入并返回结果，核心算法见方法体。
    def invertTree(self, root):
        # 递归法
        if root is None:
            return root                     # 终止条件
        root.left, root.right = root.right, root.left  # 交换左右孩子
        self.invertTree(root.left)          # 递归处理新的左子树
        self.invertTree(root.right)         # 递归处理新的右子树
        return root

    # 方法：invertTreeIterative；按题目要求处理输入并返回结果，核心算法见方法体。
    def invertTreeIterative(self, root):
        # 迭代法（栈模拟前序遍历）
        if root is None:
            return root
        stack = [root]
        while stack:
            node = stack.pop()
            node.left, node.right = node.right, node.left  # 访问即交换
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
        return root
```

二叉树节点定义：

```cpp
