    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 思路一：层序遍历，取每层第一个节点，最终保留最后一层的记录
    // 方法：findBottomLeftValueBFS；按题目要求处理输入并返回结果，核心算法见方法体。
    int findBottomLeftValueBFS(TreeNode* root) {
        queue<TreeNode*> que;
        que.push(root);
        int result = root->val;
        while (!que.empty()) {
            int size = que.size();
            for (int i = 0; i < size; i++) {
                TreeNode* node = que.front();
                que.pop();
                if (i == 0) result = node->val;   // 记录本层第一个访问到的节点（最左）
                if (node->left) que.push(node->left);
                if (node->right) que.push(node->right);
            }
        }
        return result;  // 遍历结束，result 保留的是最后一层（最底层）的最左值
    }

    // 思路二：DFS，记录最大深度，深度增加时更新结果
    int maxDepth = -1;
    int result = 0;
    // 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
    void traverse(TreeNode* node, int depth) {
        if (node == nullptr) return;
        if (node->left == nullptr && node->right == nullptr) {
            // 到达叶子节点，检查是否比当前记录的最大深度更深
            if (depth > maxDepth) {
                maxDepth = depth;      // 更新最大深度
                result = node->val;    // 更新最左值（因为前序遍历先左后右，第一次到达更深层就是最左）
            }
        }
        traverse(node->left, depth + 1);  // 先递归左子树（保证左边先被访问到）
        traverse(node->right, depth + 1); // 再递归右子树
    }
    // 方法：findBottomLeftValue；按题目要求处理输入并返回结果，核心算法见方法体。
    int findBottomLeftValue(TreeNode* root) {
        traverse(root, 0);
        return result;
    }
};
```


### Go

```go
// 思路一：层序遍历
// 方法：findBottomLeftValueBFS；按题目要求处理输入并返回结果，核心算法见方法体。
func findBottomLeftValueBFS(root *TreeNode) int {
    queue := []*TreeNode{root}
    result := root.Val
    for len(queue) > 0 {
        size := len(queue)
        for i := 0; i < size; i++ {
            node := queue[0]
            queue = queue[1:]
            if i == 0 {
                result = node.Val // 本层第一个节点即最左
            }
            if node.Left != nil {
                queue = append(queue, node.Left)
            }
            if node.Right != nil {
                queue = append(queue, node.Right)
            }
        }
    }
    return result
}

// 思路二：DFS
// 方法：findBottomLeftValue；按题目要求处理输入并返回结果，核心算法见方法体。
func findBottomLeftValue(root *TreeNode) int {
    maxDepth := -1
    result := 0
    var traverse func(node *TreeNode, depth int)
    traverse = func(node *TreeNode, depth int) {
        if node == nil {
            return
        }
        if node.Left == nil && node.Right == nil {
            if depth > maxDepth {
                maxDepth = depth  // 更新最大深度
                result = node.Val // 更新最左值
            }
        }
        traverse(node.Left, depth+1)  // 先左
        traverse(node.Right, depth+1) // 后右
    }
    traverse(root, 0)
    return result
}
```

## 总结

- 层序遍历这个解法是最直观的：每层只记录第一个被访问到的节点值，遍历结束之后留下来的就是最后一层，也就是最底层的记录，天然就满足了"最底层最左"这个要求。
- DFS 解法需要维护"当前最大深度"和"对应结果值"这两个状态，而且必须保证先递归左子树再递归右子树，这样同一深度里最左边的节点才会先被访问到，"深度增加了才更新结果"这个判断逻辑才能立得住。
- 两种解法的复杂度都是 O(n)，选哪种主要看个人偏好：BFS 写法更符合"层"的那种直觉，DFS 写法代码量稍微少一点，但要注意递归顺序不能写错。
- 这道题其实又体现了一个套路：跟"层"相关的问题优先考虑用 BFS，如果需要在遍历过程中携带额外状态（比如这里的深度），用 DFS 也能等价地解决。

07.二叉树/0530.二叉搜索树的最小绝对差/0530.二叉搜索树的最小绝对差:
# 0530. 二叉搜索树的最小绝对差

**题目描述**

给定一个二叉搜索树（BST）的根节点 `root`，返回树中任意两个不同节点值之间的最小绝对差。

```
示例：
输入: root = [4,2,6,1,3]
输出: 1
解释: 所有节点值排序后是 [1,2,3,4,6]，相邻差值分别是 1,1,1,2，最小值是 1。
```

## 思路

如果不考虑 BST 的性质，暴力解法就是把所有节点值都收集到一个数组里，排序之后遍历相邻元素求最小差值，这样时间复杂度是 O(n log n)，主要花在排序上。但既然这是一棵 BST，那我们就应该想想怎么利用它自带的有序性。

BST 的核心性质是什么呢？就是中序遍历出来的结果是一个严格递增的序列。

有了这个结论，具体实现上还能再优化一步：其实不需要真的把整个中序遍历结果存到一个数组里，因为我们只关心"相邻两个值的差"，所以可以在遍历的过程中用一个 `pre` 指针记录"上一个访问的节点"，每访问到一个新节点，就立刻用"当前节点值减去 pre 节点值"来更新最小差值，然后把 `pre` 更新成当前节点。这么一来，只需要 O(1) 的额外空间就够了（不算递归栈），而不是 O(n) 去存整个序列。

这个"pre 指针加边遍历边比较"的技巧，其实是处理"BST 相邻节点关系"这类问题的通用套路，后面讲 0501（BST 中的众数）的时候也会用到同样的模式。

递归的三要素说一下：终止条件是节点为空就直接返回，什么比较都不做；单层递归逻辑就是中序遍历——先递归左子树，然后处理当前节点，这一步要跟 `pre` 比较、更新最小差值、再更新 `pre`，最后才递归右子树。

复杂度这块，时间复杂度是 O(n)，每个节点访问一次；空间复杂度是 O(h)，h 是树的高度，这里就是递归调用栈的开销，`pre` 指针本身占的是常数空间。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：getMinimumDifference；按题目要求处理输入并返回结果，核心算法见方法体。
    def getMinimumDifference(self, root: TreeNode) -> int:
        self.pre = None            # 记录上一个访问的节点
        self.result = float("inf")  # 最小差值

        # 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
        def inorder(node: TreeNode) -> None:
            if node is None:
                return  # 终止条件
            inorder(node.left)  # 先递归左子树
            if self.pre is not None:
                self.result = min(self.result, node.val - self.pre.val)  # 更新最小差
            self.pre = node  # 更新 pre
            inorder(node.right)  # 最后递归右子树

        inorder(root)
        return self.result
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    // 方法：getMinimumDifference；按题目要求处理输入并返回结果，核心算法见方法体。
    int getMinimumDifference(TreeNode* root) {
        inorder(root);
        return result;
    }

private:
    TreeNode* pre = nullptr;      // 记录中序遍历中上一个访问的节点
    int result = INT_MAX;          // 维护当前最小差值

    // 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void inorder(TreeNode* root) {
        if (root == nullptr) return; // 终止条件：空节点
        inorder(root->left);          // 先递归左子树
        if (pre != nullptr) {
            result = min(result, root->val - pre->val); // 与上一个节点比较，更新最小差
        }
        pre = root;                    // 更新 pre 为当前节点
        inorder(root->right);          // 最后递归右子树
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：getMinimumDifference；按题目要求处理输入并返回结果，核心算法见方法体。
func getMinimumDifference(root *TreeNode) int {
    var pre *TreeNode      // 记录上一个访问的节点
    result := math.MaxInt64 // 最小差值

    var inorder func(node *TreeNode)
    inorder = func(node *TreeNode) {
        if node == nil {
            return // 终止条件
        }
        inorder(node.Left) // 先递归左子树
        if pre != nil {
            diff := node.Val - pre.Val
            if diff < result {
                result = diff // 更新最小差
            }
        }
        pre = node          // 更新 pre
        inorder(node.Right) // 最后递归右子树
    }

    inorder(root)
    return result
}
```

## 总结

- 核心结论就是：BST 中序遍历结果是严格递增的，最小差值必然出现在相邻元素之间，所以说不需要把所有节点两两组合都比较一遍，只要比较中序遍历里相邻的元素对就行。
- 用 `pre` 指针记录中序遍历的上一个节点，边遍历边比较，这样就能把"先存整个序列再遍历比较"那种 O(n) 的额外空间，优化到 O(1)（不含递归栈），这是处理 BST 相邻关系类问题的通用技巧。
- 递归结构其实还是标准的中序遍历模板，唯一的变化就是在"处理当前节点"这一步，插入了跟 `pre` 比较的逻辑。
- 这道题跟后面要讲的 0501（BST 中的众数）共享的是同一个"pre 指针加中序遍历"的模式，把这道题的写法理解透了，后面可以直接照搬过去用。

07.二叉树/0538.把二叉搜索树转换为累加树/0538.把二叉搜索树转换为累:
# 0538. 把二叉搜索树转换为累加树

**题目描述**

给定一个二叉搜索树（BST），将其转换为累加树（Greater Sum Tree），使得每个节点的值等于原来的值加上所有大于它的节点值之和。

```
示例：
输入: root = [5,2,13]
输出: [18,20,13]
解释: 节点 2 的新值 = 2 + 13 + 5 = 20；节点 5 的新值 = 5 + 13 = 18；节点 13 没有比它大的节点，新值不变。
```

## 思路

这道题跟 0530、0501 一样，都是利用了 BST 中序遍历的有序性，但方向恰好是反过来的：那两道题要的是"递增序列"，而这道题需要的是"每个节点右侧、也就是更大的那部分的和"，这自然就引出一个想法——如果按照从大到小的顺序去遍历节点，那就可以边遍历边累加，累加到当前节点的时候，这个总和正好就是所有比它大的节点值加起来的和。

你想啊，BST 标准的中序遍历顺序是"左子树、根节点、右子树"，得到的是从小到大的递增序列。那如果把这个顺序倒过来，变成"右子树、根节点、左子树"，得到的就是从大到小的递减序列了，这个叫"反中序遍历"。

按照反中序遍历去访问节点：第一个访问到的节点，是整棵树里的最大值，这时候它没有比它更大的节点了，所以新值就等于原值；第二个访问到的是次大值，比它大的节点只有"最大值"这一个，所以新值就等于原值加上最大值；依此类推，每访问到一个新节点，就把它加到一个累加变量 `pre` 上面——这个 `pre` 表示"到目前为止已经遍历过的所有节点值之和"，然后把累加后的结果作为这个节点的新值，同时更新 `pre` 为这个新值，为什么要这么更新呢？因为后面的节点还需要加上"这个节点更新后的值"。

具体展开说一下：终止条件是节点为空就直接返回；单层递归逻辑是反中序，也就是先右子树，再当前节点，最后左子树，具体是这样：

1. 先递归处理右子树，因为右子树的值都比当前节点大，得先把它们都处理完并累加上去。
2. 然后处理当前节点：`pre += root->val`，把当前节点的原值加到累加和上，接着 `root->val = pre`，把这个累加和赋值给当前节点，这样就完成了"变成累加树"的转换。
3. 最后再递归处理左子树。

这里 `pre` 变量的含义是随着遍历推进不断变化的：它始终代表"当前已经处理过的所有节点（在原树里）的值之和"，因为处理顺序是从大到小的，"已经处理过的节点"正好就是"比当前节点大的所有节点"，所以 `pre` 累加完之后立刻赋值给当前节点，这样就精确地实现了题目要求的——每个节点的值等于原值加上所有比它大的节点值之和。

这个技巧说白了本质上就是 0530 和 0501 用到的"pre 指针"模式的一个变体：不同的地方在于，这里 `pre` 存的不是"上一个节点"本身，而是"累加和"，而且遍历方向也从"从小到大"变成了"从大到小"。所以你看，只要把 pre 指针在中序遍历中的通用用法掌握了，稍微调整一下遍历方向和 `pre` 的含义，就能把这一类问题都解决掉。

复杂度这块，时间复杂度是 O(n)，每个节点访问一次；空间复杂度是 O(h)，也就是递归调用栈的开销，`pre` 本身占的是常数空间。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：convertBST；按题目要求处理输入并返回结果，核心算法见方法体。
    def convertBST(self, root: TreeNode) -> TreeNode:
        self.pre = 0  # 累加和：目前已处理过的所有节点值之和

        # 方法：reverse_inorder；按题目要求处理输入并返回结果，核心算法见方法体。
        def reverse_inorder(node: TreeNode) -> None:
            if node is None:
                return  # 终止条件
            reverse_inorder(node.right)  # 先处理右子树（值更大的部分）
            self.pre += node.val  # 累加当前节点原值
            node.val = self.pre  # 把累加和赋给当前节点
            reverse_inorder(node.left)  # 最后处理左子树

        reverse_inorder(root)
        return root
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    TreeNode* convertBST(TreeNode* root) {
        reverseInorder(root);
        return root;
    }

private:
    int pre = 0; // 累加和：目前已处理过的所有节点值之和

    // 方法：reverseInorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void reverseInorder(TreeNode* root) {
        if (root == nullptr) return; // 终止条件
        reverseInorder(root->right);  // 先处理右子树（值更大的部分）
        pre += root->val;               // 累加当前节点原值
        root->val = pre;                 // 把累加和赋给当前节点，完成转换
        reverseInorder(root->left);    // 最后处理左子树（值更小的部分）
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：convertBST；按题目要求处理输入并返回结果，核心算法见方法体。
func convertBST(root *TreeNode) *TreeNode {
    pre := 0 // 累加和

    var reverseInorder func(node *TreeNode)
    reverseInorder = func(node *TreeNode) {
        if node == nil {
            return // 终止条件
        }
        reverseInorder(node.Right) // 先处理右子树
        pre += node.Val              // 累加当前节点原值
        node.Val = pre                // 赋值给当前节点
        reverseInorder(node.Left)    // 最后处理左子树
    }

    reverseInorder(root)
    return root
}
```

## 总结

- 核心技巧就是"反中序遍历"，也就是先右子树、再当前节点、最后左子树，这样得到的访问顺序是从大到小，天然适合"累加所有比当前节点大的值"这类需求。
- `pre` 这个变量在这里扮演的角色是"到目前为止已处理节点值之和"，处理当前节点的时候要先累加原值，再把结果赋值给节点本身，这个顺序不能颠倒，不然会把累加和本身重复算进去。
- 这道题说白了就是 0530 和 0501 那种"pre 指针加中序遍历"模式的一个变体：遍历方向从"从小到大"改成了"从大到小"，`pre` 的含义也从"上一个节点"变成了"累加和"，这体现的是同一个模式在不同问题上的灵活迁移。
- 这个转换是原地修改节点的 `val`，不需要新建一棵树的结构，空间开销就只有递归调用栈，这也是这类"基于中序遍历顺序做原地统计或转换"问题典型的效率特征。

07.二叉树/0617.合并二叉树/0617.合并二叉树.md:
# 0617. 合并二叉树

**题目描述**

给定两棵二叉树 `root1` 和 `root2`，想象当你将其中一棵覆盖到另一棵上时，两棵树的一些节点会重叠，而另一些节点则不会。你需要将这两棵树合并成一棵新树。合并的规则是：如果两个节点重叠，那么将两个节点的值相加作为合并后节点的新值；否则，不为 `null` 的节点将直接作为新树的节点。

```
示例：
输入: root1 = [1,3,2,5], root2 = [2,1,3,null,4,null,7]
输出: [3,4,5,5,4,null,7]
解释: 对应位置节点值相加，root1 有的位置 root2 没有（或反过来），直接用存在的那个节点。
```

## 思路

这道题算是二叉树递归里最简单的一类了，说白了就是"同时遍历两棵树，对应位置做点处理"。核心逻辑可以归纳成一句话：只要有一个节点非空，结果树在这个位置就得有节点；只有两个节点都为空的时候，结果才是空。

具体到递归的三要素上说一下。

终止条件是这样的：如果 `root1` 为空，那就直接返回 `root2`——不管 `root2` 是不是也为空，都拿它作为结果，如果 `root2` 恰好也是空的，那返回的自然就是空。反过来，如果 `root2` 为空，就直接返回 `root1`。你看，这两个判断合起来，就已经把"至少一个为空"的所有情况都覆盖了，根本不需要再单独去判断"两个都为空"这种情况，因为那种情况早就被"`root1` 为空则返回 `root2`，此时 `root2` 也恰好为空"这一条给覆盖掉了。

单层递归逻辑是这样的：如果两个节点都非空，能走到这一步就说明两棵树在当前位置都有节点，这时候才需要真正做合并——把 `root2` 的值加到 `root1` 上面，也就是 `root1->val += root2->val`，然后递归合并左子树 `root1->left` 和 `root2->left`，把结果挂到 `root1->left` 上；右子树同理递归合并。最后返回 `root1`，作为这个位置合并完之后的节点。

那这里有个问题，要不要新建一棵树呢？上面这种写法是直接在 `root1` 的基础上改，把 `root1` 当作最终结果返回，这样能省去创建新节点的开销，但代价是会破坏 `root1` 原来的结构——如果调用者后面还要用到原始的 `root1`，这种写法就不合适了。

复杂度这块，递归只会访问两棵树中较小那部分对应的所有节点对，一旦某一边为空就停止递归了。设两棵树节点数分别是 `m` 和 `n`，那时间复杂度就是 O(min(m, n))；空间复杂度是递归调用栈的开销，也是 O(min(depth1, depth2))。

## 代码

### Python

同时遍历两棵树做合并是结构性递归，没有对应的标准库一行解，只给手写实现：

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：mergeTrees；按题目要求处理输入并返回结果，核心算法见方法体。
    def mergeTrees(self, root1: TreeNode, root2: TreeNode) -> TreeNode:
        # 复用 root1 的结构，直接在其上修改
        if root1 is None:
            return root2  # root1 为空，结果取决于 root2
        if root2 is None:
            return root1  # root2 为空，直接用 root1
        root1.val += root2.val  # 两者都非空，值相加
        root1.left = self.mergeTrees(root1.left, root2.left)    # 递归合并左子树
        root1.right = self.mergeTrees(root1.right, root2.right)  # 递归合并右子树
        return root1

    # 方法：mergeTreesNew；按题目要求处理输入并返回结果，核心算法见方法体。
    def mergeTreesNew(self, root1: TreeNode, root2: TreeNode) -> TreeNode:
        # 新建节点版本，不修改任意一棵原树
        if root1 is None:
            return root2
        if root2 is None:
            return root1
        node = TreeNode(root1.val + root2.val)  # 新建节点承载合并结果
        node.left = self.mergeTreesNew(root1.left, root2.left)
        node.right = self.mergeTreesNew(root1.right, root2.right)
        return node
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    // 复用 root1 的结构，直接在其上修改（省空间，但会破坏原树）
    TreeNode* mergeTrees(TreeNode* root1, TreeNode* root2) {
        if (root1 == nullptr) return root2; // root1 为空，结果取决于 root2（可能也为空）
        if (root2 == nullptr) return root1; // root2 为空，直接用 root1
        root1->val += root2->val;             // 两者都非空，值相加
        root1->left = mergeTrees(root1->left, root2->left);   // 递归合并左子树
        root1->right = mergeTrees(root1->right, root2->right); // 递归合并右子树
        return root1;
    }

    // 新建节点版本，不修改任意一棵原树
    TreeNode* mergeTreesNew(TreeNode* root1, TreeNode* root2) {
        if (root1 == nullptr) return root2;
        if (root2 == nullptr) return root1;
        TreeNode* node = new TreeNode(root1->val + root2->val); // 新建节点承载合并结果
        node->left = mergeTreesNew(root1->left, root2->left);
        node->right = mergeTreesNew(root1->right, root2->right);
        return node;
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 复用 root1 的结构
// 方法：mergeTrees；按题目要求处理输入并返回结果，核心算法见方法体。
func mergeTrees(root1 *TreeNode, root2 *TreeNode) *TreeNode {
    if root1 == nil {
        return root2 // root1 为空，结果取决于 root2
    }
    if root2 == nil {
        return root1 // root2 为空，直接用 root1
    }
    root1.Val += root2.Val // 两者都非空，值相加
    root1.Left = mergeTrees(root1.Left, root2.Left)     // 递归合并左子树
    root1.Right = mergeTrees(root1.Right, root2.Right)  // 递归合并右子树
    return root1
}

// 新建节点版本
// 方法：mergeTreesNew；按题目要求处理输入并返回结果，核心算法见方法体。
func mergeTreesNew(root1 *TreeNode, root2 *TreeNode) *TreeNode {
    if root1 == nil {
        return root2
    }
    if root2 == nil {
        return root1
    }
    node := &TreeNode{Val: root1.Val + root2.Val} // 新建节点
    node.Left = mergeTreesNew(root1.Left, root2.Left)
    node.Right = mergeTreesNew(root1.Right, root2.Right)
    return node
}
```

## 总结

- 合并二叉树的核心就是"两棵树同步递归"：只要有一个节点非空，结果就要保留这个位置的节点；两个都为空的时候，才是真正的空。
- 终止条件那两行判断——`root1` 为空就返回 `root2`，`root2` 为空就返回 `root1`——已经隐式地覆盖了"两者都为空"这种情况，不需要再额外判断。
- 要不要复用原树结构，这是个工程上的权衡点：复用能省空间，但会破坏原树；新建节点能保留原树，但要多花 O(n) 空间，面试的时候可以主动把这个权衡点提出来聊一聊。
- 时间复杂度取决于两棵树里比较小的那一棵，因为递归只要碰到任意一侧为空，就不会再往下深入了。

07.二叉树/0654.最大二叉树/0654.最大二叉树.md:
# 0654. 最大二叉树

**题目描述**

给定一个不含重复元素的整数数组 `nums`，请用如下方法递归地构造最大二叉树：

1. 二叉树的根是数组 `nums` 中的最大元素。
2. 左子树是通过数组中**最大值左边**的子数组构造出的最大二叉树。
3. 右子树是通过数组中**最大值右边**的子数组构造出的最大二叉树。

返回有根节点 `root`，由 `nums` 构建的最大二叉树。

```
示例：
输入: nums = [3,2,1,6,0,5]
输出: [6,3,5,null,2,0,null,null,1]
解释: 6 是最大值，左边子数组 [3,2,1] 构造左子树，右边子数组 [0,5] 构造右子树，
      递归地重复这个过程构造出整棵树。
```

## 思路

你想啊，这道题其实跟 0106（从中序与后序遍历构造二叉树）是一个套路："先找到当前区间的根节点，再拿这个根节点把区间切成左右两半，然后递归构造左右子树"。区别就在于根节点怎么找——这里更简单，不用靠遍历序列的性质去反推，题目直接告诉你了：**当前区间的最大值就是根节点**。

那具体怎么递归呢？说白了就是这么几步：

1. 在当前处理的区间 `[left, right]` 里扫一遍，找到最大值和它的下标 `maxIdx`。
2. 拿这个最大值建一个根节点。
3. 左子树递归处理区间 `[left, maxIdx-1]`，也就是最大值左边那一段。
4. 右子树递归处理区间 `[maxIdx+1, right]`，最大值右边那一段。
5. 递归的终止条件也很直白：区间为空了（`left > right`），直接返回 `null`。

那为什么这样递归下去，构造出来的树一定是唯一确定的呢？这里的关键是数组里所有元素都不重复，所以每个区间内的最大值肯定是唯一的，根节点的位置一定了，左右两个子区间自然也就唯一确定了，不会有歧义。这也是这题比 0106 简单的地方——不需要像 0106 那样额外搞个哈希表去加速定位根节点，因为找根节点和切分区间本来就是同一个动作，不用在两个不同数组之间来回换算下标。

**这里还有个值得聊的点，就是要不要原地操作还是新建子数组**。一种比较直观的写法是每次递归都用 `nums[left+1:maxIdx]`、`nums[maxIdx+1:right+1]` 这种切片方式建一个新数组传给子问题，代码看起来更直白，但问题是每次切片都要拷贝数据，最坏情况下——比如树退化成一条链，输入是严格递增或递减的序列——总的拷贝代价就变成 O(n²) 了。

再说说复杂度。每一层递归都要扫一遍当前区间去找最大值，最坏情况下——比如输入是严格递增序列，每次最大值都卡在区间最右端，整棵树退化成单链——总的扫描次数就是 `n + (n-1) + ... + 1`，时间复杂度是 O(n²)；但平均情况下，最大值大致落在区间中部，跟平衡二分差不多，那就是 O(n log n)。

## 代码

### Python

区间最大值分割是结构性递归，没有对应的标准库一行解，只给手写实现：

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：constructMaximumBinaryTree；按题目要求处理输入并返回结果，核心算法见方法体。
    def constructMaximumBinaryTree(self, nums: list[int]) -> TreeNode:
        # 方法：build；按题目要求处理输入并返回结果，核心算法见方法体。
        def build(left: int, right: int) -> TreeNode:
            if left > right:
                return None  # 区间为空
            max_idx = left
            for i in range(left + 1, right + 1):
                if nums[i] > nums[max_idx]:
                    max_idx = i  # 更新区间内最大值下标
            root = TreeNode(nums[max_idx])
            root.left = build(left, max_idx - 1)    # 左边子数组构造左子树
            root.right = build(max_idx + 1, right)   # 右边子数组构造右子树
            return root

        return build(0, len(nums) - 1)
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    TreeNode* constructMaximumBinaryTree(vector<int>& nums) {
        return build(nums, 0, nums.size() - 1);
    }

private:
    // [left, right] 闭区间
    TreeNode* build(vector<int>& nums, int left, int right) {
        if (left > right) {
            return nullptr; // 区间为空，无节点
        }
        int maxIdx = left;
        for (int i = left + 1; i <= right; i++) {
            if (nums[i] > nums[maxIdx]) {
                maxIdx = i; // 更新区间内最大值下标
            }
        }
        TreeNode* root = new TreeNode(nums[maxIdx]);
        root->left = build(nums, left, maxIdx - 1);   // 最大值左边的子数组构造左子树
        root->right = build(nums, maxIdx + 1, right);  // 最大值右边的子数组构造右子树
        return root;
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：constructMaximumBinaryTree；按题目要求处理输入并返回结果，核心算法见方法体。
func constructMaximumBinaryTree(nums []int) *TreeNode {
    var build func(left, right int) *TreeNode
    build = func(left, right int) *TreeNode {
        if left > right {
            return nil // 区间为空
        }
        maxIdx := left
        for i := left + 1; i <= right; i++ {
            if nums[i] > nums[maxIdx] {
                maxIdx = i // 更新最大值下标
            }
        }
        root := &TreeNode{Val: nums[maxIdx]}
        root.Left = build(left, maxIdx-1)   // 左边子数组构造左子树
        root.Right = build(maxIdx+1, right)  // 右边子数组构造右子树
        return root
    }
    return build(0, len(nums)-1)
}
```

## 总结

- 这道题延续的是 0106 那套核心分割思路（找根节点 -> 切分区间 -> 递归构造左右子树），只不过根节点的确定规则更简单直接：区间最大值就是根。
- 用左右边界下标在原数组上直接操作，而不是每层递归都切片新建子数组，这样能省掉额外的拷贝开销，这也是处理"区间递归构造"这类问题时通用的优化手段。
- 因为数组元素不重复，所以每个区间的最大值都是唯一的，这么一来左右子树的切分点也就唯一确定了，不会有构造上的歧义。
- 平均时间复杂度是 O(n log n)，但最坏情况下（输入近似有序）会退化到 O(n²)；如果对性能要求更高，可以考虑用单调栈把复杂度优化到 O(n)。

07.二叉树/0669.修剪二叉搜索树/0669.修剪二叉搜索树.md:
# 0669. 修剪二叉搜索树

**题目描述**

给定二叉搜索树（BST）的根节点 `root`，以及最小边界 `low` 和最大边界 `high`，通过修剪 BST，使得所有节点的值都在 `[low, high]` 区间内。修剪树**不应该改变保留在树中的元素的相对结构**（即如果没有被移除，原有的父子关系应当保留）。返回修剪后 BST 的根节点。

```
示例：
输入: root = [3,0,4,null,2,null,null,1], low = 1, high = 3
输出: [3,2,null,1]
解释: 值为 0 和 4 的节点超出了 [1,3] 区间，需要被移除，同时保留剩余节点原有的相对结构。
```

## 思路

这道题跟 0450（删除 BST 节点）其实是一类的，都是"修改 BST 结构"的问题，不过修剪操作要简单一些，因为它能充分利用 BST 的有序性去判断"哪一整片子树可以直接丢掉"，不用像删除单个节点那样去处理复杂的"用谁顶替"的问题。

这里的关键是什么呢？**如果当前节点的值小于 `low`，那你想啊，根据 BST 的性质，它整个左子树的值肯定都比它还小，那必然也都小于 `low`，所以左子树可以整体丢弃，不用再去检查了**；同时，当前节点自己也不满足要求，得被移除，但它的右子树里说不定还有满足 `[low, high]` 的节点，所以得继续递归处理右子树，而且**要用右子树修剪完的结果直接顶替当前节点的位置**。

反过来也是一样的道理，**如果当前节点的值大于 `high`，那它整个右子树都比它还大，肯定也都大于 `high`，右子树就可以整体丢弃**，这时候要递归处理左子树，并用左子树修剪后的结果去顶替当前节点的位置。

那如果当前节点的值恰好落在 `[low, high]` 区间内呢？说明这个节点本身是要保留的，这时候只需要分别递归修剪它的左子树和右子树，把修剪后的结果重新接到 `root->left` 和 `root->right` 上就行了。

把这三种情况写成递归，大概是这样：

- **终止条件**：当前节点为空，直接返回 `null`。
- **单层递归逻辑**：
  - 若 `root->val < low`：直接返回 `trim(root->right, low, high)`，也就是丢弃当前节点和整个左子树，只留右子树修剪后的结果。

**这里最容易出错的地方，就是返回值怎么正确对接**。当 `root->val < low` 的时候，直接返回 `trim(root->right, ...)` 的结果，这个返回值会被上一层递归赋值给某个指针（比如 `root->left = trim(root->left, ...)`），这意味着什么呢？

再说说复杂度。每个节点最多被访问一次——即使是被丢弃的子树，也只需要一次比较就整体跳过，不用逐一去访问它内部的每个节点，因为返回的是"递归修剪右子树/左子树"这个动作，而不是直接遍历整棵子树。不过这里要注意，"丢弃"指的是不需要单独去判断子树内每个节点是否要删除，但递归调用本身还是会进入这个子树内部继续判断，所以严格来说时间复杂度依然是 O(n)，n 是原树的节点数。空间复杂度是 O(h)，这个是递归调用栈的开销。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：trimBST；按题目要求处理输入并返回结果，核心算法见方法体。
    def trimBST(self, root: TreeNode, low: int, high: int) -> TreeNode:
        if root is None:
            return None  # 终止条件

        if root.val < low:
            # 当前节点和整个左子树都小于 low，丢弃，只保留右子树修剪结果
            return self.trimBST(root.right, low, high)
        if root.val > high:
            # 当前节点和整个右子树都大于 high，丢弃，只保留左子树修剪结果
            return self.trimBST(root.left, low, high)

        # 当前节点在合法区间内，分别修剪左右子树并接回
        root.left = self.trimBST(root.left, low, high)
        root.right = self.trimBST(root.right, low, high)
        return root
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    TreeNode* trimBST(TreeNode* root, int low, int high) {
        if (root == nullptr) {
            return nullptr; // 终止条件：空节点
        }
        if (root->val < low) {
            // 当前节点及其左子树全部小于 low，整体丢弃，只保留右子树修剪结果
            return trimBST(root->right, low, high);
        }
        if (root->val > high) {
            // 当前节点及其右子树全部大于 high，整体丢弃，只保留左子树修剪结果
            return trimBST(root->left, low, high);
        }
        // 当前节点在合法区间内，分别修剪左右子树并接回
        root->left = trimBST(root->left, low, high);
        root->right = trimBST(root->right, low, high);
        return root;
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：trimBST；按题目要求处理输入并返回结果，核心算法见方法体。
func trimBST(root *TreeNode, low, high int) *TreeNode {
    if root == nil {
        return nil // 终止条件
    }
    if root.Val < low {
        return trimBST(root.Right, low, high) // 丢弃当前节点和左子树
    }
    if root.Val > high {
        return trimBST(root.Left, low, high) // 丢弃当前节点和右子树
    }
    root.Left = trimBST(root.Left, low, high)   // 在区间内，修剪左子树
    root.Right = trimBST(root.Right, low, high) // 修剪右子树
    return root
}
```

## 总结

- 修剪 BST 的关键是利用有序性去判断"哪一整片子树必然全部超出边界"：值小于 `low` 的时候左子树整体作废，值大于 `high` 的时候右子树整体作废，不用逐一去检查子树内每个节点是否越界。
- 当前节点不合法的时候，直接返回"另一侧子树递归修剪后的结果"，这一步就完成了"跳过不合法节点、把它的子树直接接到上一层"这个操作，保证剩下的节点之间的相对结构（也就是祖先-后代关系）不被破坏。
- 和 0701、0450 一样，这里沿用的是"递归返回值重新赋值给子节点指针"这套模式，这是二叉树结构性修改类题目的通用写法。
- 虽然有些不合法的子树会被整体"跳过判断细节"，但递归调用还是会深入这些子树内部去找可能存在的合法节点，所以整体时间复杂度依然是 O(n)，不要误以为是 O(h)。

07.二叉树/0700.二叉搜索树中的搜索/0700.二叉搜索树中的搜索.md:
# 0700. 二叉搜索树中的搜索

**题目描述**

给定二叉搜索树（BST）的根节点 `root` 和一个整数值 `val`，在 BST 中找到值等于 `val` 的节点，返回该节点为根的子树。如果节点不存在，返回 `null`。

```
示例：
输入: root = [4,2,7,1,3], val = 2
输出: [2,1,3]
解释: BST 中值为 2 的节点，其子树包含 1 和 3。
```

## 思路

你想啊，如果这是一棵普通的二叉树，要查找一个值就只能老老实实两边都递归：先递归查左子树，没找到再递归查右子树，任何一边找到了就返回。这种查法的时间复杂度是 O(n)，为什么呢？因为你不知道目标值到底在哪一侧，必须把所有节点都遍历一遍，才能确保"这个值不存在"这个结论是对的。

但这道题的树是**二叉搜索树**，BST 有个核心性质——**对于任意一个节点，它左子树所有节点的值都比它小，右子树所有节点的值都比它大**。这个性质就厉害了，它能让查找像二分查找一样"剪枝"：

- 如果 `root->val == val`：那就是找到了，直接返回 `root`。
- 如果 `val < root->val`：说明目标值比当前节点还小，根据 BST 性质，它绝对不可能出现在右子树里（右子树所有值都比 `root->val` 大，自然也就比 `val` 大），所以只需要递归查左子树就行了。
- 如果 `val > root->val`：同理，只用递归查右子树。

**这里其实就是普通二叉树递归和 BST 递归最核心的区别**：普通二叉树的递归是"两边都得探测一下，因为不知道目标在哪一侧"；BST 的递归呢，是"每一步都能确定目标只可能在一侧，另一侧可以直接放弃"。这种"每次排除一半可能性"的模式，跟二分查找的思想完全是一回事——说白了，BST 的查找就是把二分查找从"有序数组"搬到了"树形结构"上，只是数组的"左半区/右半区"变成了"左子树/右子树"而已。

那递归的终止条件是什么呢？如果 `root` 为空了（走到叶子节点的下一层，或者输入本身就是空树），说明沿着这条路径找到底也没找到目标值，那就返回 `null`。

除了递归写法，这道题其实也很适合用迭代来实现，为什么呢？因为每一步只需要往一个方向走，不需要回溯，用一个指针从根节点开始不断往左或往右移动就行了，不用显式地维护一个栈。

复杂度这块，因为每一步都能排除一半的子树（假设树相对平衡），时间复杂度是 O(log n)，h 是树高；但最坏情况下，如果树退化成一条链（比如所有节点都只有右孩子），复杂度就退化到 O(n) 了。空间复杂度呢，递归写法是 O(h)，也就是调用栈的开销；迭代写法是 O(1)，因为不需要额外空间。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：searchBST；按题目要求处理输入并返回结果，核心算法见方法体。
    def searchBST(self, root: TreeNode, val: int) -> TreeNode:
        # 递归写法：利用 BST 有序性剪枝
        if root is None or root.val == val:
            return root  # 找到或未找到
        if val < root.val:
            return self.searchBST(root.left, val)  # 只查左子树
        return self.searchBST(root.right, val)  # 只查右子树

    # 方法：searchBSTIterative；按题目要求处理输入并返回结果，核心算法见方法体。
    def searchBSTIterative(self, root: TreeNode, val: int) -> TreeNode:
        # 迭代写法：不需要回溯
        while root is not None and root.val != val:
            root = root.left if val < root.val else root.right  # 决定移动方向
        return root
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    // 递归写法：利用 BST 有序性，每次只需要探测一侧
    TreeNode* searchBST(TreeNode* root, int val) {
        if (root == nullptr || root->val == val) {
            return root; // 找到或者已经走到空节点（未找到）
        }
        if (val < root->val) {
            return searchBST(root->left, val); // 目标更小，只需查左子树
        }
        return searchBST(root->right, val); // 目标更大，只需查右子树
    }

    // 迭代写法：不需要回溯，用一个指针不断往一个方向移动
    TreeNode* searchBSTIterative(TreeNode* root, int val) {
        while (root != nullptr && root->val != val) {
            root = (val < root->val) ? root->left : root->right; // 决定往左还是往右走
        }
        return root; // 循环结束时，root 是目标节点或 nullptr
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 递归写法
// 方法：searchBST；按题目要求处理输入并返回结果，核心算法见方法体。
func searchBST(root *TreeNode, val int) *TreeNode {
    if root == nil || root.Val == val {
        return root // 找到或未找到
    }
    if val < root.Val {
        return searchBST(root.Left, val) // 只查左子树
    }
    return searchBST(root.Right, val) // 只查右子树
}

// 迭代写法
// 方法：searchBSTIterative；按题目要求处理输入并返回结果，核心算法见方法体。
func searchBSTIterative(root *TreeNode, val int) *TreeNode {
    for root != nil && root.Val != val {
        if val < root.Val {
            root = root.Left // 往左走
        } else {
            root = root.Right // 往右走
        }
    }
    return root
}
```

## 总结

- BST 查找的关键就是利用"左小右大"的有序性去剪枝：每一步都能确定目标只可能在一侧，另一侧根本不用探测，这跟普通二叉树"两边都要递归"是完全不同的两种玩法。
- BST 上的查找说白了就是二分查找的思想搬到了树形结构上，把"数组的中点"换成了"当前节点"，把"数组的左右半区"换成了"左右子树"。
- 因为每一步只需要往一个方向走，不用回溯，所以这道题很适合写成迭代形式，用一个指针代替递归调用栈，这样空间复杂度就能做到 O(1)。
- 平衡 BST 上查找是 O(log n)，但如果树退化成一条链（比如插入的数据本身就是有序的），就会退化到 O(n)，这也是后面要学"平衡二叉搜索树"（比如红黑树、AVL树）的原因之一。

07.二叉树/0701.二叉搜索树中的插入操作/0701.二叉搜索树中的插入操作:
# 0701. 二叉搜索树中的插入操作

**题目描述**

给定二叉搜索树（BST）的根节点 `root` 和要插入树中的值 `val`，将值 `val` 插入到 BST 中，返回插入后 BST 的根节点。可以假设原始 BST 中不存在与 `val` 相同的值，插入操作可以以任意有效方式完成，只要在插入后，原有的每个不同值对应的节点值保持不变。

```
示例：
输入: root = [4,2,7,1,3], val = 5
输出: [4,2,7,1,3,5]
解释: 5 应该插在 4 的右子树（因为 5>4），再插在 7 的左子树（因为 5<7）。
```

## 思路

这道题的插入操作其实是在 0700（BST 中的搜索）基础上自然延伸出来的。你回想一下 0700 的查找逻辑：从根节点出发，根据目标值和当前节点值的比较结果，决定往左走还是往右走，一直走到找到目标或者走到空节点为止。插入操作走的就是同一条路径，唯一的区别在哪呢？**查找失败的时候（也就是走到空节点了），不是返回 `null`，而是在这个空位置上创建一个新节点**。

具体说说，BST 插入不需要考虑"插入后树是否平衡"这种复杂问题——那是 AVL 树、红黑树这些自平衡结构才要操心的事——这里只需要保持基本的 BST 性质（左小右大）就够了，所以插入的位置是唯一确定的：沿着"比当前节点小就往左走，比当前节点大就往右走"这条路径一直走下去，直到碰到一个空位置，把新值往这一放就完成插入了。

那递归怎么实现呢？

- **终止条件**：如果当前节点为空，说明找到插入位置了，创建一个新节点返回就行（这个新节点会被上一层递归接到 `left` 或者 `right` 上）。
- **单层递归逻辑**：
  - 如果 `val < root->val`：说明新值应该插到左子树里，那就递归调用 `insertIntoBST(root->left, val)`，然后把返回结果重新赋值给 `root->left`——这一步是关键，为什么呢？

这个"递归返回值重新赋值给子节点指针"的写法，在很多二叉树修改类题目里都会反复出现（比如后面的 0450 删除节点、0669 修剪 BST），核心思想是什么呢？**递归函数不仅要完成子树内部的修改，还得负责把修改后的子树正确地"接回"到父节点上**，调用者不用管子树内部到底发生了什么变化，只需要拿返回值去更新对应的指针就行。

当然也可以用迭代写法：用一个指针从根节点开始，按照跟查找一样的规则移动，但同时要记录"当前节点的父节点"，为什么呢？因为一旦确定要往哪个方向走结果发现是空节点，就得马上用父节点的指针把新节点接上去，不像递归那样可以靠返回值自动完成"接回"这个动作。

复杂度这块，因为只需要沿着一条路径走到底，时间复杂度是 O(h)，h 是树高，平衡树下就是 O(log n)，最坏情况（退化成链）会到 O(n)。空间复杂度呢，递归写法是 O(h)（也就是调用栈的开销），迭代写法是 O(1)。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：insertIntoBST；按题目要求处理输入并返回结果，核心算法见方法体。
    def insertIntoBST(self, root: TreeNode, val: int) -> TreeNode:
        # 递归写法
        if root is None:
            return TreeNode(val)  # 找到空位置，创建新节点

        if val < root.val:
            root.left = self.insertIntoBST(root.left, val)  # 插入左子树并接回
        else:
            root.right = self.insertIntoBST(root.right, val)  # 插入右子树并接回
        return root

    # 方法：insertIntoBSTIterative；按题目要求处理输入并返回结果，核心算法见方法体。
    def insertIntoBSTIterative(self, root: TreeNode, val: int) -> TreeNode:
        # 迭代写法
        if root is None:
            return TreeNode(val)  # 空树

        cur = root
        parent = None
        while cur is not None:
            parent = cur  # 记录父节点
            cur = cur.left if val < cur.val else cur.right

        if val < parent.val:
            parent.left = TreeNode(val)  # 接到左侧
        else:
            parent.right = TreeNode(val)  # 接到右侧
        return root
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    // 递归写法
    TreeNode* insertIntoBST(TreeNode* root, int val) {
        if (root == nullptr) {
            return new TreeNode(val); // 找到空位置，创建新节点
        }
        if (val < root->val) {
            root->left = insertIntoBST(root->left, val);  // 插入左子树，并把结果接回
        } else {
            root->right = insertIntoBST(root->right, val); // 插入右子树，并把结果接回
        }
        return root; // 当前节点本身不变，返回给上一层
    }

    // 迭代写法：需要额外记录父节点，才能把新节点接上去
    TreeNode* insertIntoBSTIterative(TreeNode* root, int val) {
        if (root == nullptr) {
            return new TreeNode(val); // 空树，新节点即为根
        }
        TreeNode* cur = root;
        TreeNode* parent = nullptr;
        while (cur != nullptr) {
            parent = cur; // 记录父节点，供后续接回新节点
            cur = (val < cur->val) ? cur->left : cur->right; // 决定移动方向
        }
        if (val < parent->val) {
            parent->left = new TreeNode(val); // 接到父节点左侧
        } else {
            parent->right = new TreeNode(val); // 接到父节点右侧
        }
        return root;
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 递归写法
// 方法：insertIntoBST；按题目要求处理输入并返回结果，核心算法见方法体。
func insertIntoBST(root *TreeNode, val int) *TreeNode {
    if root == nil {
        return &TreeNode{Val: val} // 找到空位置，创建新节点
    }
    if val < root.Val {
        root.Left = insertIntoBST(root.Left, val) // 插入左子树并接回
    } else {
        root.Right = insertIntoBST(root.Right, val) // 插入右子树并接回
    }
    return root
}

// 迭代写法
// 方法：insertIntoBSTIterative；按题目要求处理输入并返回结果，核心算法见方法体。
func insertIntoBSTIterative(root *TreeNode, val int) *TreeNode {
    if root == nil {
        return &TreeNode{Val: val} // 空树
    }
    cur := root
    var parent *TreeNode
    for cur != nil {
        parent = cur // 记录父节点
        if val < cur.Val {
            cur = cur.Left
        } else {
            cur = cur.Right
        }
    }
    if val < parent.Val {
        parent.Left = &TreeNode{Val: val} // 接到左侧
    } else {
        parent.Right = &TreeNode{Val: val} // 接到右侧
    }
    return root
}
```

## 总结

- BST 插入说白了就是沿着"比当前节点小往左、比当前节点大往右"这条路径走到空位置，插入位置是唯一确定的，不用考虑树的平衡性。
- 递归写法的关键模式是 `root.left = insertIntoBST(root.left, val)`——用递归返回值重新赋值给子节点指针，这样才能保证修改后的子树被正确"接回"父节点，这个模式后面在删除、修剪类题目里还会反复出现。
- 迭代写法需要额外维护一个 `parent` 指针，为什么呢？因为迭代过程中一旦到达空位置，就得立即用父节点的指针把新节点接上去，不像递归那样可以靠返回值自动完成。
- 时间复杂度取决于树高，也就是 O(h)，因为只需要走一条路径，不用探测整棵树，这跟 0700 的查找操作是同一类效率特征。

07.二叉树/1382.将二叉搜索树变平衡/1382.将二叉搜索树变平衡.md:
# 1382. 将二叉搜索树变平衡

**题目描述**

给定一棵二叉搜索树（BST），请将其转换为一棵**高度平衡**的二叉搜索树，返回任意一个符合要求的新二叉搜索树的根节点即可（答案不唯一）。

```
示例：
输入: root = [1,null,2,null,3,null,4,null,null]  （一条向右倾斜的链）
输出: [2,1,3,null,null,null,4]  （或任意其他高度平衡的合法 BST）
解释: 原树退化成链表形态，高度为 4；转换后的树高度平衡，高度为 2 或 3
```

要求：转换后的树必须仍然是合法的 BST（中序遍历结果不变），且任意节点的左右子树高度差不超过 1。

## 思路

这题的关键洞察是这样的：**任何一棵 BST 的中序遍历结果，都是一个严格升序的有序数组**。而"有序数组转平衡 BST"呢，这其实是一个已经解决过的经典问题，也就是 LeetCode 108 题：每次取数组的中间位置当根节点，左半部分递归构建左子树，右半部分递归构建右子树，这样构建出来的树天然就是高度平衡的，为什么呢？因为每一层的左右子树节点数量差最多是 1。

所以你看，整道题其实可以拆成两个独立的、而且都很成熟的子步骤：

**第一步：BST → 有序数组（中序遍历）**

这里的关键是，BST 的性质保证了中序遍历（左 - 根 - 右）访问节点的顺序就是数值升序的。这一步只需要做一次标准的中序遍历，把节点值依次存进数组就行，不用额外排序。

**第二步：有序数组 → 平衡 BST（也就是 108 题的方法）**

对数组区间 `[left, right]`，取中间下标 `mid = left + (right - left) / 2`（也可以取 `(left+right+1)/2`，这两种取整方式都能保证高度差不超过 1，只是构建出来的具体树形不一样，因为这题本身就允许多解）。用 `nums[mid]` 新建一个节点当当前子树的根，然后递归处理 `[left, mid-1]` 作为左子树、`[mid+1, right]` 作为右子树。

那为什么这样构建出来的一定是高度平衡的呢？因为每次划分都是从中间切开的，左右两部分的节点数量最多相差 1，这个性质在递归的每一层都成立，所以整棵树里任意节点的左右子树高度差都不会超过 1，这就满足平衡二叉树的定义了。

边界条件这块，递归到 `left > right` 的时候说明区间为空了，返回 `nullptr`（也就是空节点），这就是递归的终止条件。取中点用 `left + (right - left) / 2` 而不是 `(left + right) / 2`，是为了避免下标很大的时候发生整数溢出——虽然这题的数据规模不会真的溢出，但这是二分类问题的标准写法习惯，得养成这个习惯。

这道题真正的考点其实不是这两步本身实现起来有多难，而是你能不能识别出"BST 中序遍历能得到有序数组"和"有序数组可以确定性地构建平衡 BST"这两个知识点是可以拼在一起解决一个新问题的——这其实是一种很典型的**问题分解**能力：把一个看起来陌生的问题，转化成两个已知解法的组合。你想啊，任何 BST，不管它原来长什么形状（哪怕退化成一条链），只要能拿到它的中序遍历数组，就都能用同一套方法重建成平衡树。

复杂度这块，中序遍历会把每个节点访问一次，时间是 O(n)；重建过程也是遍历数组每个元素一次去构建一个节点，时间也是 O(n)；所以总的时间复杂度是 O(n)。空间复杂度上，存储中序数组需要 O(n)，加上递归调用栈在平衡重建时深度是 O(log n)，而原来的中序遍历如果原树退化成链的话，调用栈深度会是 O(n)，所以总体空间复杂度是 O(n)。

## 代码

### Python

标准库没有直接的一行解法能同时完成"中序遍历 + 重建平衡树"，这是一个需要显式实现两阶段算法的问题，直接给出手写实现：

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：balanceBST；按题目要求处理输入并返回结果，核心算法见方法体。
    def balanceBST(self, root: TreeNode) -> TreeNode:
        sorted_vals = []
        self._inorder(root, sorted_vals)  # 第一步：中序遍历得到有序数组
        return self._build_balanced(sorted_vals, 0, len(sorted_vals) - 1)  # 第二步：重建平衡 BST

    # 方法：_inorder；按题目要求处理输入并返回结果，核心算法见方法体。
    def _inorder(self, node: TreeNode, vals: list) -> None:
        if node is None:
            return
        self._inorder(node.left, vals)   # 先访问左子树
        vals.append(node.val)            # 再记录当前节点值（保证升序）
        self._inorder(node.right, vals)  # 最后访问右子树

    # 方法：_build_balanced；按题目要求处理输入并返回结果，核心算法见方法体。
    def _build_balanced(self, vals: list, left: int, right: int) -> TreeNode:
        if left > right:
            return None  # 区间为空
        mid = left + (right - left) // 2  # 取中点作为根
        node = TreeNode(vals[mid])
        node.left = self._build_balanced(vals, left, mid - 1)    # 左半区间构建左子树
        node.right = self._build_balanced(vals, mid + 1, right)  # 右半区间构建右子树
        return node
```

面试考察点：能不能主动联想到"BST 中序遍历有序"和"有序数组转平衡 BST"这两个知识点，并把它们串联起来，这才是这道题区分度的核心，而不是编码本身有多复杂。

### C++

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    TreeNode* balanceBST(TreeNode* root) {
        vector<int> sortedVals;
        inorder(root, sortedVals);           // 第一步：中序遍历得到有序数组
        return buildBalanced(sortedVals, 0, (int)sortedVals.size() - 1);  // 第二步：重建平衡 BST
    }

private:
    // 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void inorder(TreeNode* node, vector<int>& vals) {
        if (node == nullptr) return;
        inorder(node->left, vals);   // 先访问左子树
        vals.push_back(node->val);   // 再记录当前节点值（保证升序）
        inorder(node->right, vals);  // 最后访问右子树
    }

    TreeNode* buildBalanced(vector<int>& vals, int left, int right) {
        if (left > right) return nullptr;  // 区间为空，返回空节点
        int mid = left + (right - left) / 2;  // 取中点作为根，防止溢出
        TreeNode* node = new TreeNode(vals[mid]);
        node->left = buildBalanced(vals, left, mid - 1);   // 左半区间构建左子树
        node->right = buildBalanced(vals, mid + 1, right); // 右半区间构建右子树
        return node;
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：balanceBST；按题目要求处理输入并返回结果，核心算法见方法体。
func balanceBST(root *TreeNode) *TreeNode {
    var sortedVals []int
    inorder(root, &sortedVals)                       // 第一步：中序遍历得到有序数组
    return buildBalanced(sortedVals, 0, len(sortedVals)-1) // 第二步：重建平衡 BST
}

// 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
func inorder(node *TreeNode, vals *[]int) {
    if node == nil {
        return
    }
    inorder(node.Left, vals)          // 先访问左子树
    *vals = append(*vals, node.Val)   // 再记录当前节点值
    inorder(node.Right, vals)         // 最后访问右子树
}

// 方法：buildBalanced；按题目要求处理输入并返回结果，核心算法见方法体。
func buildBalanced(vals []int, left, right int) *TreeNode {
    if left > right {
        return nil // 区间为空
    }
    mid := left + (right-left)/2 // 取中点作为根
    node := &TreeNode{Val: vals[mid]}
    node.Left = buildBalanced(vals, left, mid-1)   // 左半区间构建左子树
    node.Right = buildBalanced(vals, mid+1, right) // 右半区间构建右子树
    return node
}
```

## 总结

- 核心技巧是"BST → 中序有序数组 → 平衡 BST"这个两段式转化，把一个新问题拆解成两个已知的经典子问题（中序遍历、108 题有序数组转平衡 BST）的组合。
- 这体现了一个通用规律：**任何 BST 都可以先转换成中序有序数组，再用同一套构建方法重建**，不管原树形态多么退化（比如完全变成一条链）都一样。
- 容易出错的地方在于取中点的下标计算要用 `left + (right - left) / 2` 来防止溢出，还有递归终止条件 `left > right` 不能写错（要是写成 `left >= right` 就会漏掉单节点区间）。
- 这题答案不唯一，只要中序遍历结果跟原树一致（也就是 BST 性质不变）而且高度平衡就行，不用纠结于非得构造出某个"标准"形态的树。

07.二叉树/二叉树的统一迭代法/二叉树的统一迭代法.md:
# 二叉树的统一迭代法

**内容概述**

上一篇讲的迭代遍历里，前序和后序的写法很接近，但中序遍历需要额外引入一个 `cur` 指针，逻辑上和另外两种不统一，代码没法直接复用。这篇讲一种"标记法"，用同一套代码模板就能写出前中后序三种迭代遍历，只需要调整节点重新入栈的相对顺序就行。

节点定义（后续代码统一使用）：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

## 思路

之前中序遍历迭代法麻烦的根本原因是什么呢？就是栈里存的节点，"弹出"和"访问"这两个动作没法绑在一起——弹出一个节点的时候，我们不知道它的左子树是不是已经处理完了，所以不能立刻访问它的值。

那标记法的思路是什么呢？说白了就是：**给每个入栈的节点带上一个"是否已经处理过一次"的标记**。第一次把某个节点压入栈的时候，只是表示"我们发现了这个节点，但还没打算访问它的值"，这时候紧接着往栈里压入一个特殊标记（比如 `nullptr`/`None`）当作"待访问"的信号，再把节点本身重新压回栈顶。等再次从栈里弹出这个节点的时候，如果发现它前面（栈顶方向）跟着一个标记，说明这是第二次遇到这个节点了，这时候才真正去访问它的值。

具体怎么做呢？我们以中序遍历为例：

1. 弹出栈顶节点 `node`。
2. 如果 `node` 不为空：按照"右、根、左"的顺序依次压栈——先压右孩子（如果有），再压 `node` 本身，然后紧跟着压一个空标记 `nullptr`，最后压左孩子（如果有）。为什么这么压呢？因为栈是后进先出，这样入栈之后，出栈顺序就会是"左、根（带标记）、右"，正好符合中序遍历的要求。
3. 如果弹出的是空标记 `nullptr`：那就说明标记后面紧跟着的就是真正要访问的节点，这时候再弹出一次，把这个节点的值加入结果就行了。

这个模板对前序、后序也完全适用，唯一需要改变的是什么呢？就是**压栈时"根、左、右"三者的相对顺序**：

- 中序（左根右）：压栈顺序为 右、根+标记、左 → 出栈顺序左、根、右
- 前序（根左右）：压栈顺序为 右、左、根+标记 → 出栈顺序根、左、右
- 后序（左右根）：压栈顺序为 根+标记、右、左 → 出栈顺序左、右、根

你看，三种遍历的代码框架完全一样，只是三行"压栈"语句的排列顺序不一样，这样就不再需要像前一篇那样为中序单独设计一个 `cur` 指针，也不需要像后序那样借助"反转结果"的技巧，说白了是一种更通用、更容易记忆的写法。

时间复杂度是 O(n)，空间复杂度是 O(n)，因为栈中最多要存储所有节点及其标记。

## 代码

### Python

```python
class Solution:
    # 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def inorderTraversal(self, root):
        # 中序遍历统一迭代法：左 -> 根 -> 右
        result = []
        stack = []
        if root:
            stack.append(root)
        while stack:
            node = stack[-1]
            if node is not None:
                stack.pop()
                if node.right:
                    stack.append(node.right)  # 右孩子先压
                stack.append(node)            # 根节点重新压回
                stack.append(None)            # 紧跟标记
                if node.left:
                    stack.append(node.left)   # 左孩子最后压
            else:
                stack.pop()                   # 弹出标记
                result.append(stack.pop().val)  # 弹出并访问真正的节点
        return result

    # 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def preorderTraversal(self, root):
        # 前序遍历统一迭代法：根 -> 左 -> 右
        result = []
        stack = []
        if root:
            stack.append(root)
        while stack:
            node = stack[-1]
            if node is not None:
                stack.pop()
                if node.right:
                    stack.append(node.right)
                if node.left:
                    stack.append(node.left)
                stack.append(node)
                stack.append(None)
            else:
                stack.pop()
                result.append(stack.pop().val)
        return result

    # 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def postorderTraversal(self, root):
        # 后序遍历统一迭代法：左 -> 右 -> 根
        result = []
        stack = []
        if root:
            stack.append(root)
        while stack:
            node = stack[-1]
            if node is not None:
                stack.pop()
                stack.append(node)
                stack.append(None)
                if node.right:
                    stack.append(node.right)
                if node.left:
                    stack.append(node.left)
            else:
                stack.pop()
                result.append(stack.pop().val)
        return result
```

### C++

```cpp
class Solution {
public:
    // 中序遍历统一迭代法：左 -> 根 -> 右
    // 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        stack<TreeNode*> st;
        if (root != nullptr) st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            if (node != nullptr) {
                st.pop();
                if (node->right) st.push(node->right); // 右孩子先压，最后出栈
                st.push(node);                          // 根节点重新压回
                st.push(nullptr);                       // 紧跟一个标记，表示下次弹出即访问
                if (node->left) st.push(node->left);    // 左孩子最后压，最先出栈
            } else {
                st.pop();                    // 弹出标记
                result.push_back(st.top()->val); // 标记后面就是真正要访问的节点
                st.pop();
            }
        }
        return result;
    }

    // 前序遍历统一迭代法：根 -> 左 -> 右
    // 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> preorderTraversal(TreeNode* root) {
        vector<int> result;
        stack<TreeNode*> st;
        if (root != nullptr) st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            if (node != nullptr) {
                st.pop();
                if (node->right) st.push(node->right); // 右孩子先压
                if (node->left) st.push(node->left);   // 左孩子次之
                st.push(node);                          // 根节点最后压，最先出栈访问
                st.push(nullptr);                       // 紧跟标记
            } else {
                st.pop();
                result.push_back(st.top()->val);
                st.pop();
            }
        }
        return result;
    }

    // 后序遍历统一迭代法：左 -> 右 -> 根
    // 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> postorderTraversal(TreeNode* root) {
        vector<int> result;
        stack<TreeNode*> st;
        if (root != nullptr) st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            if (node != nullptr) {
                st.pop();
                st.push(node);                          // 根节点先压（最后访问）
                st.push(nullptr);                       // 紧跟标记
                if (node->right) st.push(node->right);  // 右孩子次之
                if (node->left) st.push(node->left);    // 左孩子最后压，最先出栈
            } else {
                st.pop();
                result.push_back(st.top()->val);
                st.pop();
            }
        }
        return result;
    }
};
```


