```cpp
// 方法二：单调栈，按凹槽逐层结算
class Solution {
public:
    // 方法：trap；按题目要求处理输入并返回结果，核心算法见方法体。
    int trap(vector<int>& height) {
        stack<int> st;   // 栈中存下标，高度从栈底到栈顶递减
        int water = 0;
        for (int i = 0; i < (int)height.size(); i++) {
            // 当前柱子比栈顶柱子高，说明形成了凹槽的右边界
            while (!st.empty() && height[i] > height[st.top()]) {
                int mid = st.top(); st.pop(); // 槽底
                if (st.empty()) break;        // 左边没有屏障，无法蓄水
                int left = st.top();          // 凹槽左边界
                int width = i - left - 1;                          // 凹槽宽度
                int h = min(height[left], height[i]) - height[mid]; // 凹槽这一层的高度
                water += width * h;
            }
            st.push(i); // 当前下标入栈，作为新的潜在槽底
        }
        return water;
    }
};
```


### Go

```go
// 方法一：双指针
// 方法：trap；按题目要求处理输入并返回结果，核心算法见方法体。
func trap(height []int) int {
    left, right := 0, len(height)-1
    leftMax, rightMax := 0, 0
    water := 0
    for left < right {
        if height[left] > leftMax {
            leftMax = height[left]
        }
        if height[right] > rightMax {
            rightMax = height[right]
        }
        if leftMax < rightMax {
            water += leftMax - height[left] // 左边屏障更矮，决定水位
            left++
        } else {
            water += rightMax - height[right] // 右边屏障更矮或相等
            right--
        }
    }
    return water
}
```

```go
// 方法二：单调栈
// 方法：trapStack；按题目要求处理输入并返回结果，核心算法见方法体。
func trapStack(height []int) int {
    stack := make([]int, 0, len(height)) // 栈中存下标，高度递减
    water := 0
    for i, h := range height {
        for len(stack) > 0 && h > height[stack[len(stack)-1]] {
            mid := stack[len(stack)-1]
            stack = stack[:len(stack)-1] // 槽底出栈
            if len(stack) == 0 {
                break // 左边没有屏障
            }
            left := stack[len(stack)-1]      // 左边界
            width := i - left - 1             // 凹槽宽度
            depth := min(height[left], h) - height[mid] // 这一层高度
            water += width * depth
        }
        stack = append(stack, i)
    }
    return water
}

// 方法：min；按题目要求处理输入并返回结果，核心算法见方法体。
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
```

## 总结

- 接雨水这道题的核心公式就是"每一列的积水量 = min(左边最高, 右边最高) - 自身高度"，双指针法靠维护左右两个指针扫过的历史最大值，在不知道对面精确最大值的情况下，也能确定当前列的水位归属到底是谁，这样就把空间优化到了 O(1)。
- 单调栈法换了个视角来看这道题：不是一列一列地算，而是直接定位"凹槽"——左边界、槛底、右边界，一次弹栈就能同时确定凹槽的宽和高，说白了本质是"按层"累加雨水，而双指针/DP 是"按列"累加雨水，两种思路殊途同归，最后结果是一样的。
- 单调栈法里有个容易漏掉的边界条件：一旦弹出槛底之后栈变空了，说明左边根本没有更高的屏障能把水围住，这时候一定要记得 `break` 跳出内层循环。
- 双指针能简化到 O(1) 空间，关键的判断依据就是：只要 `leftMax < rightMax`，就能确定右边一定存在能挡住水的屏障（哪怕还没扫到它具体在哪），所以当前列的水位必然是由 `leftMax` 决定的。这其实是一种"提前确定归属、不用知道精确对手值"的技巧，在双指针这类问题里还挺常见的。

11.单调栈/0084.柱状图中最大的矩形/0084.柱状图中最大的矩形.md:
# 0084. 柱状图中最大的矩形

**题目描述**

给定 `n` 个非负整数，用来表示柱状图中各个柱子的高度，每个柱子彼此相邻，且宽度为 1。求在该柱状图中，能够勾勒出来的矩形的最大面积。

```
示例：
输入: heights = [2,1,5,6,2,3]
输出: 10
解释: 最大的矩形由下标2、3处的柱子（高度5、6）中较矮的高度5为矩形高，
宽度从下标2到下标3，但实际上可以扩展——
以高度5为矩形高时，宽度能扩展到下标1右边、下标4左边之间(下标2到3)，面积5*2=10。
```

## 思路

### 暴力解法与问题所在

最直接的想法就是，咱们枚举每一根柱子，把它当作矩形的高度 `heights[i]`，然后往左、往右扩展，看能扩展到多宽——也就是找到左边第一个比 `heights[i]` 矮的柱子位置 `left`，右边第一个比 `heights[i]` 矮的柱子位置 `right`，那以 `heights[i]` 为高的矩形，最大宽度就是 `right - left - 1`，面积就是 `heights[i] * (right - left - 1)`。每个 `i` 都这样算一遍，取所有面积里的最大值，就是答案。

这个思路本身是对的，但如果暴力实现（对每个 `i` 都分别往左往右线性扫一遍），那就是 O(n²) 了。问题出在哪呢？其实就是往左往右扫描的时候，会重复遍历一大堆已经比较过的柱子，效率浪费在这上面了。

### 单调栈优化：核心目标转换

那优化的关键在哪呢——能不能对每个位置 `i`，用 O(1) 均摊的代价，就求出"左边第一个比它矮的下标"和"右边第一个比它矮的下标"？这正好就是单调栈的经典用法：**维护一个从栈底到栈顶高度递增的栈**（跟接雨水的递减栈刚好是相反的，这个后面我会详细对比）。

遍历柱子数组，对每个新柱子 `heights[i]`，你想啊：

1. 只要栈不为空，并且当前高度 `heights[i]` 小于栈顶下标对应的高度，这就说明栈顶那根柱子往右扩展、扩到当前位置就必须停下来了（因为遇到了比它矮的柱子），也就是说找到了栈顶柱子"右边第一个更矮的柱子"就是当前下标 `i`。这时候就要触发结算了：
   - 弹出栈顶，记为 `mid`。

**那为什么这样做能保证结果是对的呢**？你想，栈里维护的是"从栈底到栈顶高度递增"这个性质，也就是说栈中任意一个下标 `mid`，它左边紧挨着在栈里的下标 `left` 对应的高度，一定小于 `heights[mid]`（因为能留在栈里排在 `mid` 前面，说明 `mid` 入栈的时候它还没被弹出，也就是说它比 `mid` 矮或者一样高——这里为了处理高度相等时不重复计算的问题，实际操作中弹出条件我们定为 `heights[i] < heights[st.top()]`，相等的时候不弹出，交给后面更矮的柱子统一处理，这样既不会漏算，又保证每个下标只会被弹出一次）。

### 与接雨水的对称关系

这道题和 42 题"接雨水"都是用单调栈来解决的，但栈的单调性方向刚好是反过来的，这里面有个挺有意思的对称关系：

- **接雨水**：维护的是**递减栈**（栈顶最小），要找的是"比当前元素更高的柱子"来当凹槽的边界——因为水得被两边更高的柱子围住才能蓄住，所以要找"更高"的。
- **柱状图最大矩形**：维护的是**递增栈**（栈顶最大），要找的是"比当前元素更矮的柱子"来当矩形的边界——因为矩形的高度受限于这段区间里最矮的那根柱子，一旦碰到更矮的柱子，前面那些高柱子就没法再往右扩展了，所以要找"更矮"的。

可以这么理解：接雨水是"找容器的墙"（墙必须比水面高），柱状图这道题是"找矩形的限制"（限制必须比当前柱子矮）。这两题都是通过一次单调栈遍历，把原本 O(n²) 的双向扩展查找优化成了 O(n) 的线性遍历，只不过栈的单调方向和触发弹出的比较符号（大于还是小于）正好是互为镜像的关系。

**复杂度这块说一下**：
- 时间复杂度 O(n)：加上哨兵之后，每个下标入栈一次、出栈一次，总的操作次数是线性的。
- 空间复杂度 O(n)：最坏情况下（严格递增序列），所有下标会同时压在栈里。

## 代码

### Python

```python
class Solution:
    # 方法：largestRectangleArea；按题目要求处理输入并返回结果，核心算法见方法体。
    def largestRectangleArea(self, heights: list[int]) -> int:
        h = heights + [0]  # 哨兵，保证栈中所有元素最终都会被弹出结算
        stack = []           # 栈中存下标，高度从栈底到栈顶递增
        max_area = 0
        for i, cur in enumerate(h):
            # 当前高度比栈顶柱子矮，说明栈顶柱子右边界就是当前下标
            while stack and cur < h[stack[-1]]:
                mid = stack.pop()                     # 待结算柱子
                left = stack[-1] if stack else -1      # 左边界：栈为空则视为-1
                width = i - left - 1                   # 矩形宽度
                max_area = max(max_area, h[mid] * width)
            stack.append(i)
        return max_area
```

### C++

```cpp
class Solution {
public:
    // 方法：largestRectangleArea；按题目要求处理输入并返回结果，核心算法见方法体。
    int largestRectangleArea(vector<int>& heights) {
        heights.push_back(0);       // 哨兵，保证栈中所有元素最终都会被弹出结算
        stack<int> st;                // 栈中存下标，高度从栈底到栈顶递增
        int maxArea = 0;
        for (int i = 0; i < (int)heights.size(); i++) {
            // 当前高度比栈顶柱子矮，说明栈顶柱子右边界就是当前下标
            while (!st.empty() && heights[i] < heights[st.top()]) {
                int mid = st.top(); st.pop();          // 取出待结算的柱子
                int left = st.empty() ? -1 : st.top();  // 左边界：栈为空则视为-1
                int width = i - left - 1;               // 矩形宽度
                maxArea = max(maxArea, heights[mid] * width);
            }
            st.push(i); // 当前下标入栈
        }
        heights.pop_back(); // 恢复原数组（避免副作用）
        return maxArea;
    }
};
```


### Go

```go
// 方法：largestRectangleArea；按题目要求处理输入并返回结果，核心算法见方法体。
func largestRectangleArea(heights []int) int {
    h := append(append([]int{}, heights...), 0) // 哨兵，保证栈中所有元素最终都会被弹出结算
    stack := make([]int, 0, len(h))               // 栈中存下标，高度递增
    maxArea := 0
    for i, cur := range h {
        // 当前高度比栈顶柱子矮，说明栈顶柱子右边界就是当前下标
        for len(stack) > 0 && cur < h[stack[len(stack)-1]] {
            mid := stack[len(stack)-1]
            stack = stack[:len(stack)-1] // 待结算柱子出栈
            left := -1
            if len(stack) > 0 {
                left = stack[len(stack)-1] // 左边界
            }
            width := i - left - 1// 矩形宽度
            if area := h[mid] * width; area > maxArea {
                maxArea = area
            }
        }
        stack = append(stack, i)
    }
    return maxArea
}
```

## 总结

- 这道题的核心，就是把"暴力向左向右扩展找矮柱子"这个 O(n²) 的过程，用单调栈一次遍历优化到了 O(n)：栈维护的是"从栈底到栈顶高度递增"的性质，每次弹出操作正好同时确定了被弹出柱子的左右两个"更矮边界"。
- 在数组末尾加一个高度为 0 的哨兵柱子，这是个很常用的小技巧，可以避免遍历结束之后还要单独写一段代码去处理栈里剩下的元素，让所有柱子都能在主循环里统一被结算掉。
- 这道题跟 42 题接雨水的单调栈方向刚好相反：接雨水是找"更高"的柱子来当蓄水墙（用的是递减栈），这道题是找"更矮"的柱子来当矩形边界（用的是递增栈），理解这种对称关系，有助于以后碰到单调栈题目时判断该往哪个方向维护——关键就看题目需要找的是"更大"还是"更小"的元素。
- 求矩形宽度的公式 `i - left - 1` 里，`left` 和 `i` 都是边界柱子本身（它们不算在矩形范围内），所以要减 1 把这两个边界位置排除掉，只统计中间部分的宽度。

11.单调栈/0496.下一个更大元素I/0496.下一个更大元素I.md:
# 0496. 下一个更大元素 I

**题目描述**

给定两个没有重复元素的数组 `nums1` 和 `nums2`，其中 `nums1` 是 `nums2` 的子集。对于 `nums1` 中的每个元素，找出它在 `nums2` 中对应位置右边的第一个比它大的元素，如果不存在则输出 -1。

```
示例：
输入: nums1 = [4,1,2], nums2 = [1,3,4,2]
输出: [-1,3,-1]
解释：
4 在 nums2 中的下一个更大元素不存在，输出 -1
1 在 nums2 中的下一个更大元素是 3
2 在 nums2 中的下一个更大元素不存在，输出 -1
```

## 思路

这道题其实是"单调栈"跟"哈希表"结合的一个经典模式，咱们先把题目结构理清楚，再展开讲算法。

**先看题目结构**：`nums1` 是 `nums2` 的子集，这就意味着，如果我能提前把 `nums2` 里**每一个**元素的"下一个更大元素"都算出来，那对 `nums1` 里的每个元素，直接查表就能拿到答案了，根本不需要针对 `nums1` 再单独跑一次遍历。这就是解题的关键突破口——把问题拆成两步来做：

1. 对 `nums2` 跑一遍单调栈，把 `nums2` 里每个元素的下一个更大元素都算出来，存进一个哈希表 `map`（key 是元素值，value 是它的下一个更大元素，找不到的话就记成 -1）。
2. 遍历 `nums1`，每个元素直接去 `map` 里查表，就能得到答案。

**那为什么能用元素值本身当 key 呢**？因为题目保证了 `nums2` 里没有重复元素，所以"元素值"和"下标"是一一对应的关系，用值当 key 不会产生歧义。要是数组里允许有重复元素，那就必须用下标当 key 了，再通过下标映射回原数组。

**单调栈求 nums2 的下一个更大元素**：这一步说白了跟 739 题每日温度是同一个模板——维护一个从栈底到栈顶递减的栈（这里存的是元素值而不是下标，因为咱们只关心值和值之间的映射关系，不需要算距离）。遍历 `nums2`：

1. 当前元素比栈顶元素大，说明栈顶那个元素等到了它的"下一个更大元素"，弹出栈顶并记下 `map[栈顶元素] = 当前元素`，用 `while` 循环来处理连续弹出的情况。
2. 弹出结束之后，把当前元素压进栈里，接着等被后面更大的元素结算。
3. 遍历结束以后，栈里剩下的那些元素都没找到比它更大的值，它们在 `map` 里应该记为 -1（可以提前初始化好，也可以遍历结束后统一处理，或者干脆在查询的时候用类似 `map.getOrDefault` 的方式，默认返回 -1）。

**复杂度这块**：
- 时间复杂度是 O(m + n)，其中 m 是 `nums1` 的长度，n 是 `nums2` 的长度：单调栈遍历 `nums2` 是 O(n)，查表遍历 `nums1` 是 O(m)。
- 空间复杂度是 O(n)：哈希表和栈最坏情况下都要存 n 个元素。

说白了，这种"先在大范围里把所有答案都预处理出来，再对子集查表"的思路，是一种很常见的解题技巧：一旦发现查询的集合是全集的子集，往往就可以把重复的计算合并到一次预处理里搞定。

## 代码

### Python

```python
class Solution:
    # 方法：nextGreaterElement；按题目要求处理输入并返回结果，核心算法见方法体。
    def nextGreaterElement(self, nums1: list[int], nums2: list[int]) -> list[int]:
        next_greater = {}   # 值 -> 下一个更大值
        stack = []           # 栈中存元素值，从栈底到栈顶递减
        for num in nums2:
            # 当前值比栈顶值大，弹出并记录映射
            while stack and num > stack[-1]:
                next_greater[stack.pop()] = num
            stack.append(num)  # 当前值入栈

        # 查表，get 的默认值 -1 表示没有下一个更大元素
        return [next_greater.get(num, -1) for num in nums1]
```

### C++

```cpp
class Solution {
public:
    // 方法：nextGreaterElement；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> nextGreater; // 值 -> 下一个更大值
        stack<int> st;                       // 栈中存元素值，从栈底到栈顶递减
        for (int num : nums2) {
            // 当前值比栈顶值大，弹出并记录映射
            while (!st.empty() && num > st.top()) {
                nextGreater[st.top()] = num;
                st.pop();
            }
            st.push(num); // 当前值入栈，等待被结算
        }
        // 栈中剩余元素没有找到更大值，对应 -1（下面查表时用 getOrDefault 处理，此处无需显式赋值）

        vector<int> res;
        res.reserve(nums1.size());
        for (int num : nums1) {
            // 查表，找不到说明没有下一个更大元素
            res.push_back(nextGreater.count(num) ? nextGreater[num] : -1);
        }
        return res;
    }
};
```


### Go

```go
// 方法：nextGreaterElement；按题目要求处理输入并返回结果，核心算法见方法体。
func nextGreaterElement(nums1 []int, nums2 []int) []int {
    nextGreater := make(map[int]int) // 值 -> 下一个更大值
    stack := make([]int, 0, len(nums2)) // 栈中存元素值，从栈底到栈顶递减
    for _, num := range nums2 {
        // 当前值比栈顶值大，弹出并记录映射
        for len(stack) > 0 && num > stack[len(stack)-1] {
            top := stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            nextGreater[top] = num
        }
        stack = append(stack, num) // 当前值入栈
    }

    res := make([]int, len(nums1))
    for i, num := range nums1 {
        if v, ok := nextGreater[num]; ok {
            res[i] = v // 查表成功
        } else {
            res[i] = -1 // 没有找到更大元素
        }
    }
    return res
}
```

## 总结

- 这道题的核心其实不在单调栈本身（这个模板和 739 题完全一样），关键是要识别出"子集查询"这个结构，把问题拆成"对全集预处理 + 对子集查表"两步，这样就避免了对 `nums1` 里每个元素都重复扫一遍 `nums2`。
- 因为 `nums2` 里的元素不重复，所以可以直接拿元素值当哈希表的 key；但如果存在重复元素，就必须改成用下标当 key 了，不然值会冲突覆盖。
- 单调栈这里存的是元素值而不是下标，因为咱们只需要建立"值到值"的映射关系，不涉及位置的计算（不像 739 题那样需要算下标差）。
- 哈希表查询是 O(1)，配合 O(n) 的单调栈预处理，整体复杂度就是线性的，比对 `nums1` 里每个元素都在 `nums2` 里线性扫一遍（那样是 O(m*n)）要高效得多。

11.单调栈/0503.下一个更大元素II/0503.下一个更大元素II.md:
# 0503. 下一个更大元素 II

**题目描述**

给定一个循环数组 `nums`（最后一个元素的下一个元素是数组的第一个元素），返回 `nums` 中每个元素的下一个更大元素。数字 `x` 的下一个更大的元素是指在遍历中它后面（包括循环情况下从头开始遍历）第一个比它大的数字，如果不存在则输出 -1。

```
示例：
输入: nums = [1,2,1]
输出: [2,-1,2]
解释：
第一个 1 的下一个更大元素是 2
2 找不到下一个更大元素，输出 -1
第二个 1 由于是循环数组，向后循环到开头的 2，所以下一个更大元素是 2
```

## 思路

这道题是在 496 题"下一个更大元素 I"的基础上，多加了一个"循环"的条件，重点就是怎么在不破坏单调栈这个模板的前提下，把循环处理好。

**先说说为什么普通单调栈没法直接处理循环**：单调栈遍历一次数组，只能得到"从当前位置到数组末尾"这个范围内的下一个更大元素，如果这个范围里找不到，普通做法就会认为不存在了。但循环数组是允许绕回到开头继续找的，所以数组末尾的元素可能得从头再找一遍才行。

**那怎么处理循环呢——这里有个技巧，遍历两倍长度**：其实不需要真的把数组拼接成两倍长度的新数组（虽然这样也行，但会多用 O(n) 的额外空间），更省空间的做法是让下标 `i` 从 `0` 遍历到 `2n - 1`，但是通过取模 `i % n` 映射回原数组的真实下标去取值。这样等价于"虚拟地"把数组看成两倍长度、首尾相连，但实际存储用的还是原数组，没有多占空间。

具体是怎么个流程呢：

1. 先初始化一个答案数组 `res`，长度为 n，默认值都是 -1。
2. 用栈存**下标**（注意不是值，因为要往 `res` 里写答案，得知道原始位置在哪）。

**那为什么遍历两倍长度是对的呢**？你想，对于下标 `j`（0 <= j < n），它右边能扩展查找的范围就是 `j+1, j+2, ..., n-1, 0, 1, ..., j-1`（绕一圈回到自己前一个位置为止，不会超过一整圈，因为题目要求的是"下一个"，不会用自己本身）。用虚拟下标一直遍历到 `2n-1`，相当于让每个原始下标都有机会被"第二轮"里从 `n` 到 `n+j-1` 的这些元素比较到，这正好就覆盖了绕一圈的范围，而且也不会多算（因为一旦某个下标被弹出结算过了，就不会再影响后面的判断）。

**复杂度这块**：
- 时间复杂度 O(n)：虽然遍历的长度是 2n，但这仍然是常数倍的线性复杂度；每个下标最多入栈一次、出栈一次。
- 空间复杂度 O(n)：栈和答案数组都是 O(n) 级别的，不需要真的复制出一个两倍长度的新数组。

## 代码

### Python

```python
class Solution:
    # 方法：nextGreaterElements；按题目要求处理输入并返回结果，核心算法见方法体。
    def nextGreaterElements(self, nums: list[int]) -> list[int]:
        n = len(nums)
        res = [-1] * n     # 默认-1，表示循环一圈没找到
        stack = []          # 栈中存下标，对应值从栈底到栈顶递减
        for i in range(2 * n):        # 遍历两倍长度模拟循环
            idx = i % n                # 映射回真实下标
            while stack and nums[idx] > nums[stack[-1]]:
                res[stack.pop()] = nums[idx]  # 结算
            if i < n:
                stack.append(idx)  # 仅第一轮入栈，避免重复
        return res
```

### C++

```cpp
class Solution {
public:
    // 方法：nextGreaterElements；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> nextGreaterElements(vector<int>& nums) {
        int n = nums.size();
        vector<int> res(n, -1);   // 默认值-1，表示循环一圈也没找到更大元素
        stack<int> st;             // 栈中存下标，从栈底到栈顶对应值递减
        for (int i = 0; i < 2 * n; i++) {  // 遍历两倍长度模拟循环
            int idx = i % n;                // 取模映射回真实下标
            // 当前值比栈顶下标对应的值大，弹出并结算
            while (!st.empty() && nums[idx] > nums[st.top()]) {
                res[st.top()] = nums[idx];
                st.pop();
            }
            if (i < n) {
                st.push(idx); // 只在第一轮压入，避免重复入栈同一个下标
            }
        }
        return res;
    }
};
```


### Go

```go
// 方法：nextGreaterElements；按题目要求处理输入并返回结果，核心算法见方法体。
func nextGreaterElements(nums []int) []int {
    n := len(nums)
    res := make([]int, n)
    for i := range res {
        res[i] = -1 // 默认-1，表示循环一圈没找到
    }
    stack := make([]int, 0, n) // 栈中存下标
    for i := 0; i < 2*n; i++ { // 遍历两倍长度模拟循环
        idx := i % n             // 映射回真实下标
        for len(stack) > 0 && nums[idx] > nums[stack[len(stack)-1]] {
            top := stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            res[top] = nums[idx] // 结算
        }
        if i < n {
            stack = append(stack, idx) // 仅第一轮入栈
        }
    }
    return res
}
```

## 总结

- 处理循环数组的通用技巧就是"遍历两倍长度 + 取模映射真实下标"，说白了本质上是虚拟地把数组延展成两份首尾相连，但又避免了真正复制数组带来的额外空间开销。
- 栈里必须存下标而不是值，因为最终结果要写回 `res[原下标]`，只有下标才能定位到原数组的具体位置。
- 这里有个关键的实现细节，就是"只在第一轮（`i < n`）的时候才压栈"，不然第二轮遍历的时候，同一个下标就会被重复压进去，造成结果出错或者冗余计算。
- 这道题跟 496 题的联系是：如果把"循环"这个条件去掉，这道题就退化成了对单个数组求下一个更大元素（也就是 496 题预处理 `nums2` 的那一步），循环数组只是在这个基础上把查找范围扩展了一下而已。

11.单调栈/0739.每日温度/0739.每日温度.md:
# 0739. 每日温度

**题目描述**

给定一个整数数组 `temperatures`，表示每天的气温，返回一个数组 `answer`，其中 `answer[i]` 表示对于第 `i` 天，下一个更高气温出现在几天之后。如果气温在这之后都不会升高，则该位置用 0 代替。

```
示例：
输入: temperatures = [73,74,75,71,69,72,76,73]
输出: [1,1,4,2,1,1,0,0]
解释：
第0天(73°)，下一个更高温度在第1天(74°)，间隔1天
第2天(75°)，下一个更高温度在第6天(76°)，间隔4天
第6天(76°)是全局最高，之后没有更高的，输出0
```

## 思路

这道题是单调栈的入门题，我先讲一下暴力解法，再引出单调栈的优化思路。

**先看暴力解法**：对每一天 `i`，往右扫描，找到第一个比 `temperatures[i]` 大的天数，记录间隔天数。这样两层循环下来，时间复杂度是 O(n²)。数组一长就会超时，问题出在哪呢？就是对于每一天，都要重新扫描一遍右边的所有元素，而这些扫描里其实有大量重复劳动——比如说第0天扫描的时候会经过第1、2、3天，之后这几天又会作为起点被重新扫一遍，白白浪费了。

**那单调栈的核心思路是什么呢**？能不能让每个元素只被处理一次？答案是用一个栈来保存"还没找到答案的下标"，栈里这些下标对应的温度值保持**递增**（从栈底到栈顶递增，也就是说栈顶元素最大）。

具体是怎么做的呢：从左到右遍历数组，对每个新元素 `temperatures[i]`：

1. 只要栈不为空，并且当前温度 `temperatures[i]` 比栈顶下标对应的温度高，那就说明栈顶那一天等到了它的"更高温度"，弹出栈顶下标 `j`，这时候 `answer[j] = i - j`，因为 `i` 就是 `j` 之后第一个比它温度高的那天。这一步要用 `while` 循环，因为当前这个温度可能同时打破好几个栈内元素的单调性，得连续弹出好几个。

那为什么栈里维护的下标对应的温度一定是单调递增的呢（从栈底到栈顶递增）？你想啊，因为每次入栈之前都先把"比当前温度矮"的元素全部弹出去了，剩下能留在栈里、排在当前元素前面的，肯定是比当前温度更高（或者相等）的元素——这就保证了栈内从底往上看是非递增的，或者说从顶往下看是非递减的（也就是栈顶最小）。反过来说，栈里实际维护的是一个**从栈底到栈顶递减**的序列，一旦有新元素比栈顶大，就会触发弹出结算。

**那为什么能把 O(n²) 优化到 O(n) 呢**？暴力法里，每一天都要重新往右扫一遍，产生了大量重复扫描；而单调栈法里，每个下标只会被"压入栈"一次、"弹出栈"一次，一共加起来只有 2n 次操作，整个过程就是一次线性扫描搞定的。栈的作用，说白了就相当于把"还没确定答案、正在等待被结算的下标"先暂存起来，等到条件满足了（也就是遇到更大的数）才一次性结算，这样就避免了对已经扫描过的区间重复扫描。

**复杂度这块**：
- 时间复杂度 O(n)：每个下标最多入栈一次、出栈一次。
- 空间复杂度 O(n)：最坏情况下（温度是递减序列），所有下标都会压进栈里，栈的大小能达到 n。

## 代码

### Python

```python
class Solution:
    # 方法：dailyTemperatures；按题目要求处理输入并返回结果，核心算法见方法体。
    def dailyTemperatures(self, temperatures: list[int]) -> list[int]:
        n = len(temperatures)
        answer = [0] * n          # 默认0，表示后面没有更高的
        stack = []                 # 栈中存下标，温度从栈底到栈顶递减
        for i, cur in enumerate(temperatures):
            # 当前温度比栈顶下标对应温度高，说明栈顶那天等到了更高温度
            while stack and cur > temperatures[stack[-1]]:
                j = stack.pop()
                answer[j] = i - j  # 结算：间隔天数
            stack.append(i)        # 当前下标入栈，等待被结算
        return answer
```

### C++

```cpp
class Solution {
public:
    // 方法：dailyTemperatures；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> answer(n, 0);      // 默认0，表示后面没有更高的
        stack<int> st;                 // 栈中存下标，对应温度从栈底到栈顶递减
        for (int i = 0; i < n; i++) {
            // 当前温度比栈顶下标对应的温度高，说明栈顶那天等到了更高温度
            while (!st.empty() && temperatures[i] > temperatures[st.top()]) {
                int j = st.top();
                st.pop();
                answer[j] = i - j;     // 结算：间隔天数 = 当前下标 - 栈顶下标
            }
            st.push(i);                // 当前下标入栈，等待被后面更高的温度结算
        }
        return answer;
    }
};
```


### Go

```go
// 方法：dailyTemperatures；按题目要求处理输入并返回结果，核心算法见方法体。
func dailyTemperatures(temperatures []int) []int {
    n := len(temperatures)
    answer := make([]int, n)      // 默认0
    stack := make([]int, 0, n)    // 栈中存下标，温度从栈底到栈顶递减
    for i := 0; i < n; i++ {
        // 当前温度比栈顶下标对应温度高，弹出并结算
        for len(stack) > 0 && temperatures[i] > temperatures[stack[len(stack)-1]] {
            j := stack[len(stack)-1]
            stack = stack[:len(stack)-1] // 弹出栈顶
            answer[j] = i - j            // 结算间隔天数
        }
        stack = append(stack, i) // 当前下标入栈
    }
    return answer
}
```

## 总结

- 单调栈的本质说白了就是"延迟结算"：遇到还确定不了答案的元素，先压进栈里暂存着，等到未来某个元素能触发结算条件了（这里就是"比栈顶更大"），才一次性批量弹出计算，这样就避免了暴力法里的重复扫描。
- 这道题栈里维护的是下标而不是数值本身，因为最终答案得算下标差（也就是间隔天数），要是只存数值，位置信息就丢了。
- 判断"该入栈还是该弹栈"的关键，就在于比较新元素和栈顶元素的大小关系，这决定了栈该维护成什么单调性方向（递增栈是用来找更小值的，递减栈是用来找更大值的）。这道题要找的是"下一个更大元素"，所以用的是栈内自底向上非递增的写法（也就是说，找到更大值就弹栈）。
- 时间复杂度能从 O(n²) 降到 O(n)，关键就在于每个下标只会被压入和弹出各一次，总的操作次数是线性的。

12.图论/0127.单词接龙/0127.单词接龙.md:
# 127. 单词接龙

**题目描述**

给定两个单词 `beginWord` 和 `endWord`，以及一个字典 `wordList`。规则是：每次转换只能改变单词中的一个字母，并且每次转换得到的中间单词都必须存在于 `wordList` 中。求从 `beginWord` 转换到 `endWord` 的最短转换序列的**单词个数**（包含 `beginWord` 和 `endWord` 本身）。如果不存在这样的转换序列，返回 0。

```
示例：
输入: beginWord = "hit", endWord = "cog"
      wordList = ["hot","dot","dog","lot","log","cog"]
输出: 5
解释: 最短转换序列是 "hit" -> "hot" -> "dot" -> "dog" -> "cog"，共 5 个单词
```

```
示例：
输入: beginWord = "hit", endWord = "cog"
      wordList = ["hot","dot","dog","lot","log"]
输出: 0
解释: endWord "cog" 不在 wordList 中，无法转换
```

## 思路

**如何把单词转换问题建模成图**

你看这道题表面上是个字符串变换的问题，但其实本质上就是一个最短路径问题。所以第一步咱们要做的，是把它"翻译"成图论的语言：把 `wordList` 里的每个单词看成图上的一个节点，如果两个单词只相差一个字母（也就是长度相同，恰好有一位字符不一样），那就认为它们之间连了一条边——因为一次合法的转换，说白了就是沿着这条边走一步。

这里的关键点是，这张图**不需要提前构造出来**。为什么呢？

**为什么必须用 BFS，不能用 DFS**

题目要求的是"最短转换序列的长度"，这其实是一个标准的**无权图最短路径问题**。前面理论基础篇里提到过，BFS 的遍历方式是按"层"扩散的——第一层是起点能直接到达的所有节点，第二层是从第一层节点再走一步能到达的所有节点，以此类推。因为每一步转换的"代价"都是一样的（都是改变一个字母），所以 BFS 第一次到达 `endWord` 的时候所在的层数，就精确对应了从 `beginWord` 出发的最短转换步数，这是 BFS 天然就有的性质，不需要额外证明或者比较。

那如果换成 DFS 会怎么样呢？情况就完全不一样了。

**具体实现步骤**

1. 先把 `wordList` 存入一个哈希集合 `wordSet`，方便 O(1) 判断某个单词是否存在。如果 `endWord` 不在 `wordSet` 里，直接返回 0（不可能转换成功）。

**复杂度分析**

咱们设 `wordList` 长度为 N，单词长度为 L。每个从队列中取出的单词，需要尝试 `26 × L` 种字符替换，每种替换要花 O(L) 的时间构造新字符串，再花费接近 O(L)（哈希计算本身也和字符串长度相关）的时间去哈希集合里查找。所以每个单词的处理开销是 O(26 × L²)，最多有 N 个单词会被处理（每个单词只入队一次），因此总的时间复杂度约为 **O(N × 26 × L²)**，可以近似看成 O(N·L²)。

## 代码

### Python

```python
from collections import deque

class Solution:
    # 方法：ladderLength；按题目要求处理输入并返回结果，核心算法见方法体。
    def ladderLength(self, beginWord: str, endWord: str, wordList: list[str]) -> int:
        word_set = set(wordList)  # 单词表转哈希集合，便于 O(1) 查找
        if endWord not in word_set:
            return 0  # 终点不在字典里，不可能转换成功

        queue = deque([beginWord])
        word_set.discard(beginWord)  # 起点从候选集合移除，充当 visited 标记
        step = 1  # 序列长度从 1 开始，因为要把 beginWord 自己计入

        while queue:
            level_size = len(queue)  # 固定当前层的元素个数，实现按层扩展
            for _ in range(level_size):
                cur = queue.popleft()
                for i in range(len(cur)):  # 枚举单词的每一位
                    for c in "abcdefghijklmnopqrstuvwxyz":  # 枚举该位替换成的每个字母
                        if c == cur[i]:
                            continue  # 跳过原字母
                        next_word = cur[:i] + c + cur[i + 1:]  # 构造替换后的新单词
                        if next_word == endWord:
                            return step + 1  # 命中终点，返回长度
                        if next_word in word_set:
                            word_set.discard(next_word)  # 标记 visited
                            queue.append(next_word)         # 加入下一层队列
            step += 1  # 当前层处理完毕，进入下一层
        return 0  # 队列耗尽仍未到达终点，无法转换
```

### C++

```cpp
class Solution {
public:
    // 方法：ladderLength；按题目要求处理输入并返回结果，核心算法见方法体。
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> wordSet(wordList.begin(), wordList.end()); // 单词表转哈希集合，便于 O(1) 查找
        if (wordSet.find(endWord) == wordSet.end()) {
            return 0; // 终点不在字典里，不可能转换成功
        }

        queue<string> q;
        q.push(beginWord);
        wordSet.erase(beginWord); // 起点不需要再作为候选边，顺便充当 visited 标记
        int step = 1; // 序列长度从 1 开始，因为要把 beginWord 自己计入

        while (!q.empty()) {
            int levelSize = q.size(); // 固定当前层的元素个数，实现按层扩展
            for (int i = 0; i < levelSize; i++) {
                string cur = q.front();
                q.pop();
                for (int j = 0; j < (int)cur.size(); j++) { // 枚举单词的每一位
                    char origin = cur[j];
                    for (char c = 'a'; c <= 'z'; c++) { // 枚举该位替换成的每个字母
                        if (c == origin) continue; // 跳过原字母，没有变化不算一次转换
                        cur[j] = c;
                        if (cur == endWord) {
                            return step + 1; // 命中终点，返回长度
                        }
                        if (wordSet.count(cur)) {
                            wordSet.erase(cur); // 从候选集合移除，等同于标记 visited
                            q.push(cur);         // 加入下一层队列
                        }
                    }
                    cur[j] = origin; // 恢复原字母，继续枚举下一位
                }
            }
            step++; // 当前层处理完毕，进入下一层
        }
        return 0; // 队列耗尽仍未到达终点，无法转换
    }
};
```


### Go

```go
// 方法：ladderLength；按题目要求处理输入并返回结果，核心算法见方法体。
func ladderLength(beginWord string, endWord string, wordList []string) int {
    wordSet := make(map[string]bool) // 单词表转哈希集合，便于 O(1) 查找
    for _, w := range wordList {
        wordSet[w] = true
    }
    if !wordSet[endWord] {
        return 0 // 终点不在字典里，不可能转换成功
    }

    queue := []string{beginWord}
    delete(wordSet, beginWord) // 起点从候选集合移除，充当 visited 标记
    step := 1                  // 序列长度从 1 开始，因为要把 beginWord 自己计入

    for len(queue) > 0 {
        levelSize := len(queue) // 固定当前层的元素个数，实现按层扩展
        for i := 0; i < levelSize; i++ {
            cur := queue[0]
            queue = queue[1:]
            bytes := []byte(cur)
            for j := 0; j < len(bytes); j++ { // 枚举单词的每一位
                origin := bytes[j]
                for c := byte('a'); c <= 'z'; c++ { // 枚举该位替换成的每个字母
                    if c == origin {
                        continue // 跳过原字母
                    }
                    bytes[j] = c
                    next := string(bytes)
                    if next == endWord {
                        return step + 1 // 命中终点，返回长度
                    }
                    if wordSet[next] {
                        delete(wordSet, next)          // 标记 visited
                        queue = append(queue, next)    // 加入下一层队列
                    }
                }
                bytes[j] = origin // 恢复原字母，继续枚举下一位
            }
        }
        step++ // 当前层处理完毕，进入下一层
    }
    return 0 // 队列耗尽仍未到达终点，无法转换
}
```

## 总结

- 这道题的核心就是"隐式建图"：咱们不预先枚举所有单词对之间的边，而是在 BFS 扩展的时候，对当前单词的每一位尝试替换 26 个字母，动态判断是否存在到某个邻居单词的边，这样就省去了 O(N²) 级别的建图开销。
- 必须用 BFS 而不是 DFS，因为这道题求的是最短转换序列的长度，BFS 是按层扩散的，第一次到达终点的层数就是最短路径长度；而 DFS 只能找到某一条可行路径，没法保证是最短的，要保证最短就得穷举全部路径，代价是指数级的。
- 用哈希集合而不是数组来存 `wordList`，是为了把"新单词是否可达"的判断从 O(N) 降到 O(1)；而把已访问单词直接从哈希集合里删掉，就省去了单独维护一个 `visited` 集合的空间。
- 整体时间复杂度约 O(N × 26 × L²)，这里 26×L 是每个单词能枚举出的邻居数量上限，L² 来自构造新字符串和哈希计算的开销；空间复杂度 O(N)，用在哈希集合和 BFS 队列上。

12.图论/0130.被围绕的区域/0130.被围绕的区域.md:
# 0130. 被围绕的区域

**题目描述**

给定一个 `m x n` 的二维网格 `board`，网格中只包含两种字符：`'X'` 和 `'O'`。找到所有被 `'X'` 完全包围的区域，把这些区域里的每一个 `'O'` 都变成 `'X'`。

这里"包围"有一个特殊规则：**如果一个 `'O'` 区域和网格边界上的 `'O'` 直接或间接相连（上下左右方向），那么这个区域就不算被包围**，要原样保留，不能替换。只有那些完全被 `'X'` 包裹、无法通过相邻的 `'O'` 走到边界的区域，才会被替换成 `'X'`。

```
示例：
输入：
board = [
  ["X","X","X","X"],
  ["X","O","O","X"],
  ["X","X","O","X"],
  ["X","O","X","X"]
]
输出：
board = [
  ["X","X","X","X"],
  ["X","X","X","X"],
  ["X","X","X","X"],
  ["X","O","X","X"]
]
解释：中间那一片 O（(1,1)(1,2)(2,2)）没有任何一个格子挨着边界，被 X 完全包围，所以全部变成 X。
但是 (3,1) 这个 O 本身就在网格的边界上（最后一行），它不算被包围，原样保留。
```

## 思路

这道题最容易踩的坑是**从内部出发去判断一个 `'O'` 是否被围住**：你想啊，如果对网格里每一个 `'O'` 都做一次 DFS/BFS 去看它能不能走到边界，会出现大量重复搜索，而且逻辑上也挺绕的（判断"走不到边界"是一个否定性的条件，写起来容易出错）。

那更好的思路是什么呢？换一个方向想问题：不去找"被围住的"，而是先找出"绝对不会被围住的"，剩下的自然就是被围住的了。

这里的关键是，一个 `'O'` 只要能通过相邻的 `'O'` 一路连到边界，它就不会被替换。所以咱们可以反过来做：

1. **从边界出发做标记**：遍历网格最外层一圈（第一行、最后一行、第一列、最后一列）的所有格子，如果某个格子是 `'O'`，就从它出发做一次 DFS（或 BFS），把所有与它上下左右相连的 `'O'` 都标记成"安全"（比如临时改成一个特殊字符 `'A'`，或者用一个 `visited` 二维数组记录）。这一步会把所有"能连到边界"的 `'O'` 全部标记出来，不管它们离边界有多远，只要是连通的都会被找到。

2. **二次遍历整个网格**：把网格再扫一遍，这时候就只剩两种情况了——被标记为"安全"的格子（说明连到了边界，要还原成 `'O'`），和没有被标记的、原本是 `'O'` 的格子（说明无法连到边界，也就是被包围的区域，替换成 `'X'`）。

这个"先从边界反向标记安全区，再统一处理剩余部分"的做法，其实是网格类图论题里一个很通用的范式，好处是每个格子只会在标记阶段被访问一次（因为一旦标记就不会重复进入 DFS），不存在从每个 `'O'` 各自出发搜索的重复计算问题。

**与 1020 题（飞地的数量）的对比**

这道题和 1020 题"飞地的数量"几乎是同一套模板，甚至可以说是同一段代码换了最后一步的输出方式：

- 两题都是"从边界出发标记安全区，再遍历网格处理剩余部分"；
- 1020 题的"安全区"是与边界相连的陆地（`1`），本题的"安全区"是与边界相连的 `'O'`，标记逻辑完全一致；
- 唯一的区别就在最后一步怎么处理"剩余部分"：1020 题是**统计**没被标记的陆地格子数量（作为飞地数量返回），本题是**修改**没被标记的 `'O'` 格子（原地替换成 `'X'`）。

如果把这两题的 DFS/BFS 标记部分抽出来看，代码结构可以完全共用，只是调用方在最后一步一个做累加计数，一个做原地写入。理解了这一层，你就会发现图论里大量"网格 + 边界"类问题都可以套用同一个模板：**先反向标记出不会被处理的部分，再对网格做一次线性遍历完成最终结果**。

**复杂度分析**

设网格大小为 `m x n`。标记阶段每个格子最多进入一次 DFS/BFS（靠标记去重），边界格子数是 O(m+n)，但递归展开后覆盖的仍是整个连通分量，整体访问次数不超过 `m*n`；二次遍历是 O(m*n)。所以总的时间复杂度就是 O(m*n)，空间复杂度主要是递归栈（DFS 最坏 O(m*n)）或者 BFS 队列 O(m*n)。

## 代码

### Python

图论题这里没有能一行解决的标准库函数，直接给手写 DFS 实现：

```python
class Solution:
    # 方法：solve；按题目要求处理输入并返回结果，核心算法见方法体。
    def solve(self, board: list[list[str]]) -> None:
        if not board:
            return
        m, n = len(board), len(board[0])

        # 方法：dfs；按题目要求处理输入并返回结果，核心算法见方法体。
        def dfs(row: int, col: int) -> None:
            # 越界或不是待标记的 O，直接终止
            if row < 0 or row >= m or col < 0 or col >= n:
                return
            if board[row][col] != 'O':
                return
            board[row][col] = 'A'  # 标记为安全区，防止重复访问
            dfs(row - 1, col)  # 上
            dfs(row + 1, col)  # 下
            dfs(row, col - 1)  # 左
            dfs(row, col + 1)  # 右

        # 第一遍：只从四条边界出发标记安全区
        for i in range(m):
            dfs(i, 0)      # 最左列
            dfs(i, n - 1)  # 最右列
        for j in range(n):
            dfs(0, j)      # 最上行
            dfs(m - 1, j)  # 最下行

        # 第二遍：把没被标记的 O 变成 X，把标记过的 A 还原成 O
        for i in range(m):
            for j in range(n):
                if board[i][j] == 'O':
                    board[i][j] = 'X'  # 被围住，替换
                elif board[i][j] == 'A':
                    board[i][j] = 'O'  # 安全，还原
```

### C++

```cpp
class Solution {
public:
    // 方法：solve；按题目要求处理输入并返回结果，核心算法见方法体。
    void solve(vector<vector<char>>& board) {
        int m = board.size(), n = board[0].size();

        // 从 (row, col) 出发做 DFS，把相连的 'O' 标记为安全字符 'A'
        function<void(int, int)> dfs = [&](int row, int col) {
            if (row < 0 || row >= m || col < 0 || col >= n) return; // 越界，终止
            if (board[row][col] != 'O') return; // 不是待标记的 O，终止（包括已标记过的 A）
            board[row][col] = 'A'; // 标记为安全区，防止重复访问，同时作为最终还原的依据
            dfs(row - 1, col); // 上
            dfs(row + 1, col); // 下
            dfs(row, col - 1); // 左
            dfs(row, col + 1); // 右
        };

        // 第一遍：只从四条边界出发标记安全区
        for (int i = 0; i < m; i++) {
            dfs(i, 0);     // 最左列
            dfs(i, n - 1); // 最右列
        }
        for (int j = 0; j < n; j++) {
            dfs(0, j);     // 最上行
            dfs(m - 1, j); // 最下行
        }

        // 第二遍：把没被标记的 O 变成 X，把标记过的 A 还原成 O
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'O') board[i][j] = 'X'; // 未连到边界，被围住，替换
                else if (board[i][j] == 'A') board[i][j] = 'O'; // 连到边界，安全，还原
            }
        }
    }
};
```


