class Solution {
public:
    int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};  // 上下左右四个方向的偏移量

    // 方法：bfs；按题目要求处理输入并返回结果，核心算法见方法体。
    void bfs(vector<vector<char>>& grid, vector<vector<bool>>& visited, int row, int col) {
        queue<pair<int,int>> q;
        q.push({row, col});
        visited[row][col] = true;  // 入队即标记，防止被重复加入队列

        while (!q.empty()) {
            auto [curRow, curCol] = q.front();
            q.pop();  // 弹出队头，处理它的四个方向

            for (auto& d : dirs) {
                int nextRow = curRow + d[0];
                int nextCol = curCol + d[1];
                // 越界跳过
                if (nextRow < 0 || nextRow >= grid.size() || nextCol < 0 || nextCol >= grid[0].size()) continue;
                // 已访问或是水域，跳过
                if (visited[nextRow][nextCol] || grid[nextRow][nextCol] == '0') continue;

                visited[nextRow][nextCol] = true;  // 入队时立刻标记
                q.push({nextRow, nextCol});
            }
        }
    }

    // 方法：numIslands；按题目要求处理输入并返回结果，核心算法见方法体。
    int numIslands(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<bool>> visited(m, vector<bool>(n, false));
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // 找到一个还没被感染过的陆地，说明发现了新岛屿
                if (grid[i][j] == '1' && !visited[i][j]) {
                    count++;                      // 岛屿数+1
                    bfs(grid, visited, i, j);    // 用BFS感染整片相连陆地
                }
            }
        }
        return count;
    }
};
