func numIslands(grid [][]byte) int {
    m, n := len(grid), len(grid[0])
    visited := make([][]bool, m)
    for i := range visited {
        visited[i] = make([]bool, n)
    }
    dirs := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}  // 上下左右四个方向

    bfs := func(row, col int) {
        queue := [][2]int{{row, col}}
        visited[row][col] = true  // 入队即标记

        for len(queue) > 0 {
            cur := queue[0]  // 弹出队头
            queue = queue[1:]

            for _, d := range dirs {
                nextRow, nextCol := cur[0]+d[0], cur[1]+d[1]
                if nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n {
                    continue // 越界跳过
                }
                if visited[nextRow][nextCol] || grid[nextRow][nextCol] == '0' {
                    continue // 已访问或水域跳过
                }

                visited[nextRow][nextCol] = true  // 入队时立刻标记，避免重复入队
                queue = append(queue, [2]int{nextRow, nextCol})
            }
        }
    }

    count := 0
    for i := 0; i < m; i++ {
        for j := 0; j < n; j++ {
            if grid[i][j] == '1' && !visited[i][j] {
                count++          // 发现新岛屿，计数+1
                bfs(i, j)        // BFS感染整片相连陆地
            }
        }
    }
    return count
}
